declare
  v_user_id uuid := auth.uid();
  v_req public.team_join_requests%rowtype;
  v_role public.team_role := 'member'::public.team_role;
begin
  if v_user_id is null then
    raise exception using errcode = '42501', message = 'Unauthorized';
  end if;

  select *
    into v_req
  from public.team_join_requests
  where team_join_requests.id = p_request_id
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'Join request not found';
  end if;

  if v_req.status <> 'pending'::public.join_request_status then
    raise exception using errcode = '23514', message = 'Request already decided';
  end if;

  if not public.is_team_admin(v_req.team_id) then
    raise exception using errcode = '42501', message = 'Only owners or admins may approve join requests.';
  end if;

  if v_req.invite_id is not null then
    update public.team_invites ti
      set uses_count = coalesce(ti.uses_count, 0) + 1
    where ti.id = v_req.invite_id
      and ti.team_id = v_req.team_id
      and (ti.expires_at is null or ti.expires_at > now())
      and (ti.max_uses is null or coalesce(ti.uses_count, 0) < ti.max_uses)
    returning ti.role into v_role;

    if not found then
      raise exception using errcode = '23514', message = 'Invite is invalid for this request';
    end if;
  end if;

  insert into public.team_members (team_id, user_id, role)
  values (v_req.team_id, v_req.requester_user_id, v_role)
  on conflict (team_id, user_id) do nothing;

  return query
  update public.team_join_requests r
     set status = 'approved'::public.join_request_status,
         decided_by = v_user_id,
         decided_at = now()
   where r.id = v_req.id
     and r.status = 'pending'::public.join_request_status
  returning r.id, r.team_id, r.requester_user_id, r.invite_id;

  if not found then
    raise exception using errcode = '23514', message = 'Request already decided';
  end if;
end;

begin
  if new.gateway_request_id is null or new.gateway_request_created_at is null then
    select request.id, request.created_at
    into new.gateway_request_id, new.gateway_request_created_at
    from public.gateway_requests request
    where request.workspace_id = new.workspace_id
      and request.request_id = new.request_id
    order by
      case when request.created_at = new.occurred_at then 0 else 1 end,
      abs(extract(epoch from (request.created_at - new.occurred_at))),
      request.created_at desc
    limit 1;
  end if;

  if new.gateway_request_id is null or new.gateway_request_created_at is null then
    raise exception using
      errcode = '23503',
      message = 'v2_request_fact_requires_gateway_request';
  end if;

  return new;
end;

declare
  v_count bigint;
begin
  update public.gateway_requests
  set usage = usage
  where created_at >= p_since
    and created_at < p_until;

  get diagnostics v_count = row_count;
  return v_count;
end;

begin
  perform p_workspace_id;
  perform p_spend_30d_nanos;
  return 'basic';
end;

DECLARE
    v_spend_nanos bigint;
    v_spend_usd numeric(12, 2);
    v_prev_month_start timestamptz;
    v_prev_month_end timestamptz;
BEGIN
    -- Calculate previous calendar month boundaries
    v_prev_month_start := date_trunc('month', now() - interval '1 month');
    v_prev_month_end := date_trunc('month', now());

    -- Sum all successful request costs from previous month
    SELECT COALESCE(SUM(cost_nanos), 0)
    INTO v_spend_nanos
    FROM private.v2_rpc_gateway_requests_compat
    WHERE team_id = p_team_id
      AND success = true
      AND created_at >= v_prev_month_start
      AND created_at < v_prev_month_end;

    -- Convert nanos to USD
    v_spend_usd := ROUND((v_spend_nanos::numeric / 1000000000.0)::numeric, 2);

    RETURN v_spend_usd;
END;

declare
  v_row public.gateway_async_webhook_deliveries%rowtype;
begin
  if p_workspace_id is null or coalesce(trim(p_kind), '') = ''
     or coalesce(trim(p_internal_id), '') = '' or coalesce(trim(p_delivery_key), '') = ''
     or coalesce(trim(p_claim_token), '') = '' then
    raise exception 'invalid_webhook_delivery_claim';
  end if;

  insert into public.gateway_async_webhook_deliveries (
    workspace_id, kind, internal_id, delivery_key, status, claim_token, claimed_at, updated_at
  ) values (
    p_workspace_id, p_kind, p_internal_id, p_delivery_key, 'claimed', p_claim_token, now(), now()
  ) on conflict do nothing;

  select * into v_row
  from public.gateway_async_webhook_deliveries
  where workspace_id = p_workspace_id and kind = p_kind
    and internal_id = p_internal_id and delivery_key = p_delivery_key
  for update;

  if v_row.status = 'delivered' then return false; end if;
  if v_row.status = 'claimed' and v_row.claim_token <> p_claim_token
     and v_row.claimed_at > now() - make_interval(secs => greatest(30, p_stale_after_seconds)) then
    return false;
  end if;

  update public.gateway_async_webhook_deliveries
  set status = 'claimed', claim_token = p_claim_token, claimed_at = now(), updated_at = now()
  where workspace_id = p_workspace_id and kind = p_kind
    and internal_id = p_internal_id and delivery_key = p_delivery_key;
  return true;
end;

