begin
  delete from public.oauth_authorization_codes where expires_at < now() - interval '1 hour';
  delete from public.oauth_device_codes where expires_at < now() - interval '1 hour';
  delete from public.oauth_refresh_tokens token
  where token.expires_at < now() - interval '1 day'
    and not exists (
      select 1 from public.oauth_refresh_tokens child
      where child.rotated_from = token.id
    );
end;

declare
  deleted_count integer := 0;
begin
  if exists (
    select 1
    from jsonb_to_recordset(coalesce(p_current_models, '[]'::jsonb)) as model(provider_id text)
    where not (model.provider_id = any(coalesce(p_provider_ids, array[]::text[])))
  ) then
    raise exception 'Snapshot contains a provider outside p_provider_ids';
  end if;

  with current_models as (
    select model.provider_id, model.model_id
    from jsonb_to_recordset(coalesce(p_current_models, '[]'::jsonb)) as model(
      provider_id text,
      model_id text
    )
  ), deleted as (
    delete from public.model_discovery_seen_models seen
    where seen.provider_id = any(coalesce(p_provider_ids, array[]::text[]))
      and not exists (
        select 1 from current_models current
        where current.provider_id = seen.provider_id and current.model_id = seen.model_id
      )
    returning 1
  )
  select count(*) into deleted_count from deleted;

  insert into public.model_discovery_seen_models (
    provider_id,
    provider_name,
    model_id,
    model_details,
    pricing_details,
    last_seen_at,
    last_run_id
  )
  select
    model.provider_id,
    model.provider_name,
    model.model_id,
    coalesce(model.model_details, '{}'::jsonb),
    model.pricing_details,
    coalesce(model.last_seen_at, now()),
    p_run_id
  from jsonb_to_recordset(coalesce(p_current_models, '[]'::jsonb)) as model(
    provider_id text,
    provider_name text,
    model_id text,
    model_details jsonb,
    pricing_details jsonb,
    last_seen_at timestamptz
  )
  on conflict (provider_id, model_id) do update set
    provider_name = excluded.provider_name,
    model_details = excluded.model_details,
    pricing_details = excluded.pricing_details,
    last_seen_at = excluded.last_seen_at,
    last_run_id = excluded.last_run_id;

  return deleted_count;
end;

declare
  granted_scopes text[];
begin
  if not (coalesce(p_scopes, array[]::text[]) @> array['gateway:access']::text[]) then
    return 'invalid';
  end if;

  -- Match the workspace-member deletion trigger's lock order.
  perform 1
  from public.workspace_members member
  where member.user_id = p_user_id
    and member.workspace_id = p_workspace_id
  for key share;

  if not found then
    return 'invalid';
  end if;

  perform 1
  from public.oauth_authorizations authorization_row
  where authorization_row.user_id = p_user_id
    and authorization_row.workspace_id = p_workspace_id
    and authorization_row.client_id = p_client_id
    and authorization_row.revoked_at is null
    and coalesce(authorization_row.scopes, array[]::text[]) @> array['gateway:access']::text[]
  for update;

  if not found then
    return 'invalid';
  end if;

  update public.oauth_authorization_codes authorization_code
  set used_at = now()
  where authorization_code.id = p_code_id
    and authorization_code.used_at is null
    and authorization_code.expires_at > now()
    and authorization_code.user_id = p_user_id
    and authorization_code.workspace_id = p_workspace_id
    and authorization_code.client_id = p_client_id
    and coalesce(authorization_code.scopes, array[]::text[]) @> array['gateway:access']::text[]
    and coalesce(authorization_code.scopes, array[]::text[]) <@ coalesce(p_scopes, array[]::text[])
    and coalesce(p_scopes, array[]::text[]) <@ coalesce(authorization_code.scopes, array[]::text[])
  returning authorization_code.scopes into granted_scopes;

  if not found then
    return 'invalid';
  end if;

  update public.keys
  set status = 'revoked'
  where key_kind = 'oauth_delegated'
    and oauth_user_id = p_user_id
    and workspace_id = p_workspace_id
    and oauth_client_id = p_client_id
    and status = 'active';

  insert into public.keys (
    workspace_id, name, hash, prefix, status, scopes, created_by, kid,
    key_kind, oauth_client_id, oauth_user_id, oauth_scopes, issued_via
  ) values (
    p_workspace_id, p_key_name, p_key_hash, p_key_prefix, 'active', '[]', p_user_id, p_key_kid,
    'oauth_delegated', p_client_id, p_user_id, granted_scopes, 'oauth_pkce'
  );

  return 'issued';
end;

declare
  granted_scopes text[];
  granted_resource text;
  resource_is_gateway boolean;
begin
  resource_is_gateway := coalesce(
    btrim(p_resource) ~* '^https://api\.phaseo\.app(?::443)?/v1/*$',
    false
  );

  -- Unbound and Gateway-bound credentials both authorize billable API use.
  if (nullif(btrim(p_resource), '') is null or resource_is_gateway)
    and not (coalesce(p_scopes, array[]::text[]) @> array['gateway:access']::text[])
  then
    return 'invalid';
  end if;

  perform 1
  from public.workspace_members member
  where member.user_id = p_user_id
    and member.workspace_id = p_workspace_id
  for key share;

  if not found then
    return 'invalid';
  end if;

  perform 1
  from public.oauth_authorizations authorization_row
  where authorization_row.user_id = p_user_id
    and authorization_row.workspace_id = p_workspace_id
    and authorization_row.client_id = p_client_id
    and authorization_row.revoked_at is null
    and coalesce(authorization_row.scopes, array[]::text[]) @> coalesce(p_scopes, array[]::text[])
    and (
      (nullif(btrim(p_resource), '') is not null and not resource_is_gateway)
      or coalesce(authorization_row.scopes, array[]::text[]) @> array['gateway:access']::text[]
    )
  for update;

  if not found then
    return 'invalid';
  end if;

  update public.oauth_authorization_codes authorization_code
  set used_at = now()
  where authorization_code.id = p_code_id
    and authorization_code.used_at is null
    and authorization_code.expires_at > now()
    and authorization_code.user_id = p_user_id
    and authorization_code.workspace_id = p_workspace_id
    and authorization_code.client_id = p_client_id
    and authorization_code.resource is not distinct from nullif(btrim(p_resource), '')
    and (
      (authorization_code.resource is not null and not resource_is_gateway)
      or coalesce(authorization_code.scopes, array[]::text[]) @> array['gateway:access']::text[]
    )
    and coalesce(authorization_code.scopes, array[]::text[]) <@ coalesce(p_scopes, array[]::text[])
    and coalesce(p_scopes, array[]::text[]) <@ coalesce(authorization_code.scopes, array[]::text[])
  returning authorization_code.scopes, authorization_code.resource
    into granted_scopes, granted_resource;

  if not found then
    return 'invalid';
  end if;

  update public.keys
  set status = 'revoked'
  where key_kind = 'oauth_delegated'
    and oauth_user_id = p_user_id
    and workspace_id = p_workspace_id
    and oauth_client_id = p_client_id
    and oauth_resource is not distinct from granted_resource
    and status = 'active';

  insert into public.keys (
    workspace_id, name, hash, prefix, status, scopes, created_by, kid,
    key_kind, oauth_client_id, oauth_user_id, oauth_scopes, oauth_resource, issued_via, expires_at
  ) values (
    p_workspace_id, p_key_name, p_key_hash, p_key_prefix, 'active', '[]', p_user_id, p_key_kid,
    'oauth_delegated', p_client_id, p_user_id, granted_scopes, granted_resource, 'oauth_pkce', now() + interval '7 days'
  );

  return 'issued';
end;

begin
  -- Lock membership before authorization to match the member-delete trigger.
  perform 1
  from public.workspace_members member
  where member.user_id = p_user_id
    and member.workspace_id = p_workspace_id
  for key share;

  if not found then
    return 'invalid';
  end if;

  perform 1
  from public.oauth_authorizations authorization_row
  where authorization_row.user_id = p_user_id
    and authorization_row.workspace_id = p_workspace_id
    and authorization_row.client_id = p_client_id
    and authorization_row.revoked_at is null
  for update;

  if not found then
    return 'invalid';
  end if;

  if p_grant_type = 'device_code' then
    update public.oauth_device_codes device_code
    set consumed_at = now()
    where device_code.id = p_grant_id
      and device_code.consumed_at is null
      and device_code.status = 'approved'
      and device_code.expires_at > now()
      and device_code.user_id = p_user_id
      and device_code.workspace_id = p_workspace_id
      and device_code.client_id = p_client_id;
  elsif p_grant_type = 'authorization_code' then
    update public.oauth_authorization_codes authorization_code
    set used_at = now()
    where authorization_code.id = p_grant_id
      and authorization_code.used_at is null
      and authorization_code.expires_at > now()
      and authorization_code.user_id = p_user_id
      and authorization_code.workspace_id = p_workspace_id
      and authorization_code.client_id = p_client_id;
  else
    return 'invalid';
  end if;

  if not found then
    return 'invalid';
  end if;

  insert into public.oauth_refresh_tokens (
    token_hash, user_id, workspace_id, client_id, scopes, expires_at, family_id
  ) values (
    p_token_hash, p_user_id, p_workspace_id, p_client_id, p_scopes, p_expires_at, p_family_id
  );

  return 'issued';
end;

declare
  performance jsonb := coalesce(new.safe_metadata->'performance', '{}'::jsonb);
begin
  if performance ? 'provider_ttft_ms' then
    new.provider_ttft_ms := nullif(greatest(0, round(nullif(performance->>'provider_ttft_ms', '')::numeric)), 0)::integer;
  end if;
  if performance ? 'gateway_ttft_ms' then
    new.gateway_ttft_ms := nullif(greatest(0, round(nullif(performance->>'gateway_ttft_ms', '')::numeric)), 0)::integer;
  end if;
  if performance ? 'output_speed_tps' then
    new.output_speed_tps := nullif(greatest(0, nullif(performance->>'output_speed_tps', '')::numeric), 0);
  end if;
  if performance ? 'tpot_ms' then
    new.tpot_ms := nullif(greatest(0, nullif(performance->>'tpot_ms', '')::numeric), 0);
  end if;
  if performance ? 'itl_ms' then
    new.itl_ms := nullif(greatest(0, nullif(performance->>'itl_ms', '')::numeric), 0);
  end if;
  if performance ? 'phaseo_overhead_ms' then
    new.phaseo_overhead_ms := greatest(0, round(nullif(performance->>'phaseo_overhead_ms', '')::numeric))::integer;
  end if;
  return new;
end;

declare
  v_new_balance bigint;
  v_low_threshold bigint;
  v_auto_top_up_amount bigint;
  v_auto_top_up_enabled boolean;
  v_auto_top_up_account_id text;
  v_stripe_customer_id text;
begin
  if p_cost_nanos is null or p_cost_nanos <= 0 then
    raise exception 'invalid_cost_nanos';
  end if;
  update public.wallets
  set balance_nanos = balance_nanos - p_cost_nanos
  where workspace_id = p_workspace_id
    and balance_nanos - p_cost_nanos >= coalesce(reserved_nanos, 0)
  returning balance_nanos, low_balance_threshold, auto_top_up_amount,
    auto_top_up_enabled, auto_top_up_account_id, stripe_customer_id
  into v_new_balance, v_low_threshold, v_auto_top_up_amount,
    v_auto_top_up_enabled, v_auto_top_up_account_id, v_stripe_customer_id;

  if v_new_balance is null then
    if exists (select 1 from public.wallets where workspace_id = p_workspace_id) then
      raise exception 'insufficient_unreserved_balance';
    end if;
    return json_build_object('status', 'wallet_not_found');
  end if;
  if v_auto_top_up_enabled and v_new_balance < v_low_threshold then
    return json_build_object(
      'status', 'top_up_required',
      'auto_top_up_amount_nanos', v_auto_top_up_amount,
      'auto_top_up_account_id', v_auto_top_up_account_id,
      'stripe_customer_id', v_stripe_customer_id,
      'new_balance_nanos', v_new_balance
    );
  end if;
  return json_build_object('status', 'top_up_not_required', 'new_balance_nanos', v_new_balance);
end;

begin
  if nullif(new.publisher_handle, '') is null then
    new.publisher_handle := lower(regexp_replace(regexp_replace(coalesce(nullif(new.slug, ''), new.name), '[^a-zA-Z0-9_-]+', '-', 'g'), '^-+|-+$', '', 'g'));
    if length(new.publisher_handle) < 3 then
      new.publisher_handle := 'workspace-' || left(new.id::text, 8);
    end if;
  end if;
  return new;
end

declare
  existing_key_count integer;
  excluded_key_id uuid;
begin
  if tg_op = 'UPDATE'
    and new.workspace_id is not distinct from old.workspace_id
    and new.provider_id is not distinct from old.provider_id then
    return new;
  end if;

  if tg_op = 'UPDATE' then
    excluded_key_id := old.id;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(new.workspace_id::text || ':' || new.provider_id, 0)
  );

  select count(*)
  into existing_key_count
  from public.byok_keys
  where workspace_id = new.workspace_id
    and provider_id = new.provider_id
    and (excluded_key_id is null or id <> excluded_key_id);

  if existing_key_count >= 32 then
    raise exception 'BYOK key limit reached for workspace provider'
      using errcode = '23514';
  end if;

  return new;
end;

declare
  device public.oauth_device_codes%rowtype;
begin
  select * into device
  from public.oauth_device_codes
  where id = p_device_id
  for update;

  if not found then return 'invalid'; end if;

  if device.last_polled_at is not null
     and device.last_polled_at + make_interval(secs => device.interval_seconds) > now() then
    update public.oauth_device_codes
    set last_polled_at = now(), interval_seconds = interval_seconds + 5
    where id = p_device_id;
    return 'slow_down';
  end if;

  update public.oauth_device_codes set last_polled_at = now() where id = p_device_id;
  return 'ok';
end;

begin
  if lower(coalesce(new.role::text, '')) not in ('admin', 'member') then
    raise exception using
      errcode = '23514',
      message = 'invalid_workspace_invite_role',
      detail = 'Invite roles are restricted to admin and member.';
  end if;

  return new;
end;

begin
  if new.invite_id is not null then
    if not exists (
      select 1
      from public.team_invites ti
      where ti.id = new.invite_id
        and ti.team_id = new.team_id
    ) then
      raise exception using
        errcode = '23514',
        message = 'invite_team_mismatch',
        detail = 'Join request invite must belong to the same team.';
    end if;
  end if;

  if tg_op = 'INSERT' then
    if new.status <> 'pending'::join_request_status
       or new.decided_by is not null
       or new.decided_at is not null then
      raise exception using
        errcode = '23514',
        message = 'invalid_join_request_insert_state',
        detail = 'New join requests must be pending and undecided.';
    end if;
    return new;
  end if;

  -- UPDATE path
  if old.status <> 'pending'::join_request_status then
    raise exception using
      errcode = '23514',
      message = 'join_request_already_decided',
      detail = 'Only pending join requests can be updated.';
  end if;

  if new.status not in ('approved'::join_request_status, 'denied'::join_request_status) then
    raise exception using
      errcode = '23514',
      message = 'invalid_join_request_status_transition',
      detail = 'Join request updates must transition to approved or denied.';
  end if;

  if new.decided_by is null or new.decided_at is null then
    raise exception using
      errcode = '23514',
      message = 'join_request_decision_metadata_required',
      detail = 'Decided join requests must include decided_by and decided_at.';
  end if;

  if new.team_id <> old.team_id or new.requester_user_id <> old.requester_user_id then
    raise exception using
      errcode = '23514',
      message = 'join_request_immutable_fields_modified',
      detail = 'team_id and requester_user_id are immutable.';
  end if;

  if new.invite_id is distinct from old.invite_id then
    raise exception using
      errcode = '23514',
      message = 'join_request_invite_immutable',
      detail = 'invite_id is immutable after request creation.';
  end if;

  return new;
end;

declare
  v_owner_user_id uuid;
begin
  select w.owner_user_id
    into v_owner_user_id
  from public.workspaces w
  where w.id = new.workspace_id;

  if v_owner_user_id is null then
    raise exception using
      errcode = '23514',
      message = 'workspace_not_found_for_membership';
  end if;

  if new.user_id = v_owner_user_id then
    new.role := 'owner'::public.workspace_role;
    return new;
  end if;

  if lower(coalesce(new.role::text, '')) = 'owner' then
    raise exception using
      errcode = '23514',
      message = 'owner_role_reserved_for_workspace_owner',
      detail = 'Only workspaces.owner_user_id may have role=owner.';
  end if;

  if lower(coalesce(new.role::text, '')) not in ('admin', 'member') then
    raise exception using
      errcode = '23514',
      message = 'invalid_workspace_member_role',
      detail = 'Assignable roles are admin and member.';
  end if;

  return new;
end;

insert into public.gateway_async_webhook_deliveries (
  workspace_id, kind, internal_id, delivery_key, status,
  event_type, phase, progress, previous_status, current_status,
  next_attempt_at, updated_at
) values (
  p_workspace_id, p_kind, p_internal_id, p_delivery_key, 'pending',
  p_event_type, p_phase, p_progress, p_previous_status, p_current_status,
  now(), now()
) on conflict (workspace_id, kind, internal_id, delivery_key) do nothing;

declare
  v_webhook_url text;
  v_request_id bigint;
  v_created_at text;
  v_stage text := 'start';
  v_error_message text;
  v_error_sqlstate text;
  v_error_detail text;
begin
  raise log '[signup-trigger] stage=start status=ok user_id=% email=%',
    new.id,
    coalesce(new.email, '');

  -- Mandatory: if this fails, abort signup.
  v_stage := 'public_users_upsert';
  begin
    insert into public.users (user_id)
    values (new.id)
    on conflict (user_id) do nothing;

    raise log '[signup-trigger] stage=% status=ok user_id=%', v_stage, new.id;
  exception when others then
    get stacked diagnostics
      v_error_message = message_text,
      v_error_sqlstate = returned_sqlstate,
      v_error_detail = pg_exception_detail;

    raise warning '[signup-trigger] stage=% status=error severity=mandatory user_id=% sqlstate=% message=% detail=%',
      v_stage,
      new.id,
      coalesce(v_error_sqlstate, ''),
      coalesce(v_error_message, sqlerrm),
      coalesce(v_error_detail, '');

    raise;
  end;

  -- Optional: direct Discord notify for each new auth user.
  v_stage := 'discord_webhook_url_resolve';
  v_webhook_url := nullif(trim(current_setting('app.settings.discord_signup_webhook_url', true)), '');
  if v_webhook_url is null then
    raise log '[signup-trigger] stage=% status=skip reason=discord_signup_webhook_url_not_configured user_id=%',
      v_stage,
      new.id;
    return new;
  end if;

  v_created_at := coalesce(new.created_at::text, (now() at time zone 'utc')::text);

  v_stage := 'discord_webhook_request';
  begin
    select net.http_post(
      url := v_webhook_url,
      headers := jsonb_build_object('Content-Type', 'application/json'),
      body := jsonb_build_object(
        'content',
        'New AI Stats signup' || E'\n' ||
        '- user_id: `' || new.id::text || '`' || E'\n' ||
        '- email: `' || coalesce(new.email, 'unknown') || '`' || E'\n' ||
        '- created_at: `' || v_created_at || '`',
        'allowed_mentions',
        jsonb_build_object('parse', jsonb_build_array())
      )
    )
    into v_request_id;

    raise log '[signup-trigger] stage=% status=ok user_id=% request_id=%', v_stage, new.id, v_request_id;
  exception when others then
    get stacked diagnostics
      v_error_message = message_text,
      v_error_sqlstate = returned_sqlstate,
      v_error_detail = pg_exception_detail;

    raise warning '[signup-trigger] stage=% status=error severity=optional user_id=% sqlstate=% message=% detail=%',
      v_stage,
      new.id,
      coalesce(v_error_sqlstate, ''),
      coalesce(v_error_message, sqlerrm),
      coalesce(v_error_detail, '');
  end;

  return new;
exception when others then
  get stacked diagnostics
    v_error_message = message_text,
    v_error_sqlstate = returned_sqlstate,
    v_error_detail = pg_exception_detail;

  raise warning '[signup-trigger] stage=% status=fatal user_id=% sqlstate=% message=% detail=%',
    coalesce(v_stage, 'unknown'),
    new.id,
    coalesce(v_error_sqlstate, ''),
    coalesce(v_error_message, sqlerrm),
    coalesce(v_error_detail, '');

  raise;
end;

declare
  v_cur_month timestamptz;
  v_last_month timestamptz;
  v_gateway_partition_name text;
  v_upstream_partition_name text;
begin
  if months_ahead is null or months_ahead < 0 then
    raise exception 'months_ahead must be >= 0';
  end if;

  v_cur_month := date_trunc('month', now());
  v_last_month := v_cur_month + make_interval(months => months_ahead);
  while v_cur_month <= v_last_month loop
    v_gateway_partition_name := format('gateway_requests_%s', to_char(v_cur_month, 'YYYY_MM'));
    execute format(
      'create table if not exists public.%I partition of public.gateway_requests for values from (%L) to (%L)',
      v_gateway_partition_name,
      v_cur_month,
      v_cur_month + interval '1 month'
    );
    v_upstream_partition_name := format('gateway_upstream_requests_%s', to_char(v_cur_month, 'YYYY_MM'));
    execute format(
      'create table if not exists public.%I partition of public.gateway_upstream_requests for values from (%L) to (%L)',
      v_upstream_partition_name,
      v_cur_month,
      v_cur_month + interval '1 month'
    );
    v_cur_month := v_cur_month + interval '1 month';
  end loop;
end;

declare initial_version_id uuid;
begin
  insert into public.preset_lineage values (new.id, new.id, 0) on conflict do nothing;
  if new.source_preset_id is not null then
    insert into public.preset_lineage (ancestor_preset_id, descendant_preset_id, depth)
    select ancestor_preset_id, new.id, depth + 1 from public.preset_lineage
    where descendant_preset_id = new.source_preset_id on conflict do nothing;
  end if;
  insert into public.preset_versions (preset_id, version_number, version_label, versioning_method, name, slug, description, config, visibility, created_by)
  values (new.id, 1, case new.versioning_method when 'semver' then '1.0.0' when 'date' then to_char(current_date, 'YYYY.MM.DD') else 'v1' end, new.versioning_method, new.name, new.slug, new.description, new.config, new.visibility, new.created_by)
  returning id into initial_version_id;
  update public.presets set
    draft_name = new.name, draft_slug = new.slug, draft_description = new.description,
    draft_config = new.config, draft_visibility = new.visibility, active_version_id = initial_version_id
  where id = new.id;
  return new;
end

declare
  v_previous text;
  v_current text := lower(coalesce(new.status, ''));
  v_terminal_phase text;
begin
  if new.kind <> 'video'
     or new.meta->'webhook' is null
     or new.meta->'webhook' = 'null'::jsonb then
    return new;
  end if;

  if tg_op = 'INSERT' then
    perform public.enqueue_gateway_async_webhook_delivery(
      new.workspace_id, new.kind, new.internal_id,
      'video.created', 'video.created', 'created', null, null, v_current
    );
    return new;
  end if;

  v_previous := lower(coalesce(old.status, ''));
  if v_previous = v_current then return new; end if;

  perform public.enqueue_gateway_async_webhook_delivery(
    new.workspace_id, new.kind, new.internal_id,
    'video.status_changed:' || coalesce(nullif(v_previous, ''), 'unknown') || ':' || coalesce(nullif(v_current, ''), 'unknown'),
    'video.status_changed', 'status_changed', null,
    nullif(v_previous, ''), nullif(v_current, '')
  );

  v_terminal_phase := case v_current
    when 'completed' then 'completed'
    when 'failed' then 'failed'
    when 'cancelled' then 'cancelled'
    when 'canceled' then 'cancelled'
    when 'expired' then 'expired'
    else null
  end;
  if v_terminal_phase is not null then
    perform public.enqueue_gateway_async_webhook_delivery(
      new.workspace_id, new.kind, new.internal_id,
      'video.' || v_terminal_phase,
      'video.' || v_terminal_phase,
      v_terminal_phase,
      null,
      nullif(v_previous, ''),
      nullif(v_current, '')
    );
  end if;
  return new;
end;

declare
  v_hour_count bigint;
  v_day_bytes bigint;
begin
  if p_workspace_id is null or coalesce(trim(p_upload_id), '') = '' or p_bytes is null or p_bytes <= 0 then
    raise exception 'invalid_batch_file_upload_claim';
  end if;
  if p_bytes > 20971520 then
    return query select false, 'batch_file_too_large'::text;
    return;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('batch-file:' || p_workspace_id::text, 0));
  if not exists (
    select 1 from public.wallets
    where workspace_id = p_workspace_id
      and coalesce(balance_nanos, 0) - coalesce(reserved_nanos, 0) > 0
  ) then
    return query select false, 'insufficient_funds'::text;
    return;
  end if;
  select count(*) into v_hour_count
  from public.gateway_batch_file_uploads
  where workspace_id = p_workspace_id and created_at >= now() - interval '1 hour';
  if v_hour_count >= 20 then
    return query select false, 'batch_file_hourly_quota_exceeded'::text;
    return;
  end if;
  select coalesce(sum(bytes), 0) into v_day_bytes
  from public.gateway_batch_file_uploads
  where workspace_id = p_workspace_id and created_at >= now() - interval '24 hours';
  if v_day_bytes + p_bytes > 104857600 then
    return query select false, 'batch_file_daily_bytes_exceeded'::text;
    return;
  end if;
  insert into public.gateway_batch_file_uploads (workspace_id, upload_id, bytes, status)
  values (p_workspace_id, p_upload_id, p_bytes, 'claimed')
  on conflict (workspace_id, upload_id) do nothing;
  if not found then
    return query select false, 'batch_file_upload_already_claimed'::text;
    return;
  end if;
  return query select true, null::text;
end;

declare
  v_claimed integer;
begin
  update public.gateway_provider_events event
  set replay_locked_at = now(),
      replay_locked_by = left(coalesce(nullif(trim(p_worker_id), ''), 'batch-provider-webhook'), 200),
      updated_at = now()
  where event.provider = nullif(trim(p_provider), '')
    and event.provider_event_id = nullif(trim(p_provider_event_id), '')
    and event.processed_at is null
    and event.dead_lettered_at is null
    and (event.next_attempt_at is null or event.next_attempt_at <= now())
    and (
      event.replay_locked_at is null
      or event.replay_locked_at < now() - make_interval(
        secs => greatest(30, least(coalesce(p_lease_seconds, 120), 3600))
      )
    );

  get diagnostics v_claimed = row_count;
  return v_claimed = 1;
end;

begin
  if new.status = 'released' and old.status is distinct from new.status and new.key_id is not null then
    delete from public.gateway_requests
    where workspace_id = new.workspace_id
      and key_id = new.key_id
      and request_id like 'batch_hold_usage:' || new.reservation_id || ':%';
  end if;
  return new;
end;

declare
  v_charge public.gateway_request_charges%rowtype;
  v_result record;
  v_result_json jsonb;
  v_status text;
  v_auto_top_up_amount_nanos bigint;
  v_auto_top_up_account_id text;
  v_stripe_customer_id text;
begin
  if p_workspace_id is null then
    raise exception 'missing_workspace_id';
  end if;

  if coalesce(trim(p_request_id), '') = '' then
    raise exception 'missing_request_id';
  end if;

  if p_cost_nanos is null or p_cost_nanos <= 0 then
    raise exception 'invalid_cost_nanos';
  end if;

  insert into public.gateway_request_charges (
    workspace_id,
    request_id,
    cost_nanos,
    status,
    created_at,
    updated_at
  ) values (
    p_workspace_id,
    p_request_id,
    p_cost_nanos,
    'applying',
    now(),
    now()
  )
  on conflict (workspace_id, request_id) do nothing;

  select *
  into v_charge
  from public.gateway_request_charges
  where workspace_id = p_workspace_id
    and request_id = p_request_id
  for update;

  if not found then
    raise exception 'gateway_request_charge_row_missing';
  end if;

  if v_charge.cost_nanos <> p_cost_nanos then
    raise exception 'request_charge_amount_mismatch';
  end if;

  if v_charge.status = 'applied' then
    return query
    select
      false,
      true,
      coalesce(v_charge.deducted_status, 'already_applied')::text,
      0::bigint,
      null::text,
      null::text;
    return;
  end if;

  update public.gateway_request_charges
  set status = 'applying',
      error_message = null,
      updated_at = now()
  where workspace_id = p_workspace_id
    and request_id = p_request_id;

  begin
    select *
    into v_result
    from public.deduct_and_check_top_up(
      p_workspace_id := p_workspace_id,
      p_cost_nanos := p_cost_nanos
    );

    v_result_json := to_jsonb(v_result);
  exception when others then
    update public.gateway_request_charges
    set status = 'failed',
        error_message = sqlerrm,
        updated_at = now()
    where workspace_id = p_workspace_id
      and request_id = p_request_id;
    raise;
  end;

  v_status := coalesce(
    nullif(trim(v_result_json ->> 'status'), ''),
    nullif(trim(v_result_json ->> 'result'), ''),
    nullif(trim(v_result_json ->> 'deduct_and_check_top_up'), ''),
    'unknown'
  );

  v_auto_top_up_amount_nanos := case
    when coalesce(v_result_json ->> 'auto_top_up_amount_nanos', '') ~ '^-?[0-9]+$'
      then (v_result_json ->> 'auto_top_up_amount_nanos')::bigint
    when coalesce(v_result_json ->> 'auto_top_up_amount', '') ~ '^-?[0-9]+$'
      then (v_result_json ->> 'auto_top_up_amount')::bigint
    else 0::bigint
  end;

  v_auto_top_up_account_id := nullif(
    coalesce(
      v_result_json ->> 'auto_top_up_account_id',
      v_result_json ->> 'auto_top_up_payment_method_id',
      ''
    ),
    ''
  );

  v_stripe_customer_id := nullif(v_result_json ->> 'stripe_customer_id', '');

  update public.gateway_request_charges
  set status = 'applied',
      deducted_status = v_status,
      auto_top_up_required = v_status = 'top_up_required',
      updated_at = now()
  where workspace_id = p_workspace_id
    and request_id = p_request_id;

  return query
  select
    true,
    false,
    v_status,
    v_auto_top_up_amount_nanos,
    v_auto_top_up_account_id,
    v_stripe_customer_id;
end;

declare
  v_next_attempt integer;
begin
  select attempt_count + 1 into v_next_attempt
  from public.gateway_provider_events
  where provider = p_provider and provider_event_id = p_provider_event_id
  for update;
  if not found then return; end if;

  update public.gateway_provider_events
  set attempt_count = v_next_attempt,
      last_error = left(coalesce(p_reason, 'provider_event_deferred'), 500),
      next_attempt_at = case
        when v_next_attempt >= 20 then null
        else now() + make_interval(secs => least(1800, 5 * (2 ^ least(v_next_attempt, 8))::integer))
      end,
      dead_lettered_at = case when v_next_attempt >= 20 then now() else dead_lettered_at end,
      processed_at = case when v_next_attempt >= 20 then now() else processed_at end,
      replay_locked_at = null,
      replay_locked_by = null,
      updated_at = now()
  where provider = p_provider and provider_event_id = p_provider_event_id;
end;

declare
  credit_status       jsonb;
  key_status          jsonb;
  key_limit_status    jsonb;
  min_balance_nanos   bigint := 1000000000; -- 1.00 USD

  providers           jsonb;
  pricing             jsonb;
  preset_data         jsonb := null;

  -- key row fields
  v_key_active        boolean;
  v_key_team_ok       boolean;
  v_soft_blocked      boolean;

  v_day_req_limit     bigint;
  v_wk_req_limit      bigint;
  v_mo_req_limit      bigint;
  v_day_cost_limit    bigint;
  v_wk_cost_limit     bigint;
  v_mo_cost_limit     bigint;

  now_utc             timestamptz := (now() at time zone 'utc');
  day_start           timestamptz := date_trunc('day',  now_utc);
  week_start          timestamptz := date_trunc('week', now_utc);   -- Monday 00:00 UTC
  month_start         timestamptz := date_trunc('month', now_utc);

  used_day_reqs       bigint;
  used_wk_reqs        bigint;
  used_mo_reqs        bigint;
  used_day_cost       bigint;
  used_wk_cost        bigint;
  used_mo_cost        bigint;

  within_limits       boolean := true;
  limit_reason        text := null;
  limit_window        text := null;
  limit_metric        text := null;
  current_value       bigint := null;
  limit_value         bigint := null;
  limit_reset_at      timestamptz := null;

  -- Preset handling
  is_preset           boolean := false;
  preset_name         text := null;
  preset_publisher    text := null;

  -- Resolve model from alias if exists
  resolved_model      text := gateway_fetch_request_context.model;
  base_model          text;

  team_enrichment     jsonb;
  key_enrichment      jsonb;

  -- Team aggregates
  team_total_requests bigint;
  team_total_spend_nanos bigint;
  team_spend_24h_nanos bigint;
  team_spend_7d_nanos bigint;
  team_spend_30d_nanos bigint;
  team_requests_1h bigint;
  team_requests_24h bigint;
  team_created_at timestamptz;
  team_tier text;
  team_balance_nanos bigint;
  team_reserved_nanos bigint;

  -- Key aggregates
  key_name text;
  key_created_at timestamptz;
  key_total_requests bigint;
  key_total_spend_nanos bigint;
begin
  base_model := gateway_fetch_request_context.model;
  -- hard requirement: key must be provided
  if gateway_fetch_request_context.api_key_id is null then
    raise exception using errcode = '22023', message = 'missing_api_key', detail = 'api_key_id is required';
  end if;

  -- Check if model is a preset (starts with @)
  if base_model like '@%' then
    is_preset := true;
    preset_name := substring(base_model from 2); -- Remove @ prefix

    -- Fetch preset configuration. Qualified references resolve a
    -- public publisher globally; unqualified references remain workspace-local.
    if position('/' in preset_name) > 0 then
      preset_publisher := split_part(preset_name, '/', 1);
      preset_name := substring(preset_name from position('/' in preset_name) + 1);
      select jsonb_build_object(
        'id', p.id, 'name', p.name, 'slug', p.slug, 'description', p.description,
        'config', p.config, 'visibility', p.visibility, 'publisher', w.publisher_handle
      ) into preset_data
      from public.presets p
      join public.workspaces w on w.id = p.workspace_id
      where p.archived_at is null and lower(p.slug) = lower(preset_name)
        and p.visibility = 'public'
        and true
        and (lower(w.publisher_handle) = lower(preset_publisher) or exists (select 1 from public.workspace_publisher_handle_aliases alias where alias.workspace_id = w.id and alias.handle = lower(preset_publisher)))
      limit 1;
    else
      select jsonb_build_object(
        'id', p.id, 'name', p.name,
        'slug', coalesce(nullif(p.slug, ''), regexp_replace(p.name, '^@', '')),
        'description', p.description, 'config', p.config, 'visibility', p.visibility
      ) into preset_data
      from public.presets p
      where p.archived_at is null and lower(coalesce(nullif(p.slug, ''), regexp_replace(p.name, '^@', ''))) = lower(preset_name)
        and p.workspace_id = gateway_fetch_request_context.workspace_id
        and (
          p.visibility in ('public', 'team')
          or p.created_by = (
            select ak.created_by from public.keys ak
            where ak.id = gateway_fetch_request_context.api_key_id
              and ak.workspace_id = gateway_fetch_request_context.workspace_id
              and ak.status = 'active'
          )
        )
      limit 1;
    end if;

    if preset_data is null then
      raise exception using
        errcode = '22023',
        message = 'preset_not_found',
        detail = format('Preset "%s" not found or not accessible', preset_name);
    end if;

    -- Extract model from preset config (fallback to default/default_model/model/first models entry)
    base_model := coalesce(
      preset_data->'config'->>'defaultModel',
      preset_data->'config'->>'default_model',
      preset_data->'config'->>'model',
      preset_data->'config'->'models'->>0,
      preset_data->'config'->'allowedModels'->>0,
      preset_data->'config'->'allowed_models'->>0
    );

    if base_model is null then
      raise exception using
        errcode = '22023',
        message = 'preset_no_model',
        detail = format('Preset "%s" has no model configured', preset_name);
    end if;
  end if;

  -- Resolve alias/model indirection:
  -- 1) explicit alias table (`v2_model_aliases`)
  -- 2) provider-scoped slug form (`provider/provider_model_slug`)
  resolved_model := coalesce(
    (
      select a.api_model_id
      from (select alias_slug, model_slug as api_model_id, enabled as is_enabled from public.v2_model_aliases) a
      where a.alias_slug = base_model
        and a.is_enabled = true
        and a.api_model_id is not null
      limit 1
    ),
    (
      select m.api_model_id
      from (select provider_model_id as provider_api_model_id, provider_slug as provider_id, model_slug as api_model_id, model_slug as model_id, provider_model_slug, routing_enabled as is_active_gateway, status as routing_status, input_modalities, output_modalities, context_length, max_output_tokens, effective_from, effective_to, created_at, updated_at from public.v2_model_provider_routes) m
      where position('/' in base_model) > 0
        and m.provider_id = split_part(base_model, '/', 1)
        and m.provider_model_slug = regexp_replace(base_model, '^[^/]+/', '')
        and m.is_active_gateway
        and (m.effective_from is null or m.effective_from <= now() at time zone 'utc')
        and (m.effective_to   is null or (now() at time zone 'utc') < m.effective_to)
      order by coalesce(m.effective_from, to_timestamp(0)) desc, m.provider_api_model_id
      limit 1
    ),
    base_model
  );

  -- validate key row, status, and team
  select
    (k.status = 'active'),
    (k.workspace_id = gateway_fetch_request_context.workspace_id),
    k.soft_blocked,
    k.daily_limit_requests,   k.weekly_limit_requests,   k.monthly_limit_requests,
    k.daily_limit_cost_nanos, k.weekly_limit_cost_nanos, k.monthly_limit_cost_nanos
  into
    v_key_active,
    v_key_team_ok,
    v_soft_blocked,
    v_day_req_limit, v_wk_req_limit, v_mo_req_limit,
    v_day_cost_limit, v_wk_cost_limit, v_mo_cost_limit
  from public.keys k
  where k.id = gateway_fetch_request_context.api_key_id
  limit 1;

  if v_key_active is null then
    raise exception using errcode = '22023', message = 'api_key_not_found', detail = 'key id does not exist';
  end if;
  if not v_key_team_ok then
    raise exception using errcode = '22023', message = 'api_key_wrong_team', detail = 'key does not belong to provided workspace_id';
  end if;
  if not v_key_active then
    raise exception using errcode = '22023', message = 'api_key_inactive', detail = 'key status is not active';
  end if;

  key_status := jsonb_build_object('ok', true, 'mode', 'first_party');

  -- credit check
  credit_status :=
    coalesce((
      select case
        when greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0) >= min_balance_nanos then
          jsonb_build_object(
            'ok', true,
            'balance_nanos', greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0),
            'raw_balance_nanos', coalesce(w.balance_nanos, 0)::bigint,
            'reserved_nanos', coalesce(w.reserved_nanos, 0)::bigint,
            'available_nanos', greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0)
          )
        else
          jsonb_build_object(
            'ok', false,
            'reason', 'insufficient_funds',
            'balance_nanos', greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0),
            'raw_balance_nanos', coalesce(w.balance_nanos, 0)::bigint,
            'reserved_nanos', coalesce(w.reserved_nanos, 0)::bigint,
            'available_nanos', greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0)
          )
      end
      from public.wallets w
      where w.workspace_id = gateway_fetch_request_context.workspace_id
      limit 1
    ), jsonb_build_object('ok', false, 'reason', 'wallet_missing'));

  -- per-key limits (requests + cost)
  select
    count(*) filter (where gr.created_at >= day_start)                                  as used_day_reqs,
    count(*) filter (where gr.created_at >= week_start)                                 as used_wk_reqs,
    count(*) filter (where gr.created_at >= month_start)                                as used_mo_reqs,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= day_start), 0)::bigint   as used_day_cost,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= week_start), 0)::bigint  as used_wk_cost,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= month_start), 0)::bigint as used_mo_cost
  into
    used_day_reqs, used_wk_reqs, used_mo_reqs,
    used_day_cost, used_wk_cost, used_mo_cost
  from public.gateway_requests gr
  where gr.key_id  = gateway_fetch_request_context.api_key_id
    and gr.workspace_id = gateway_fetch_request_context.workspace_id
    and gr.success is true;

  if v_soft_blocked then
    within_limits := false;
    limit_reason := 'key_limit_soft_blocked';
    limit_metric := 'soft_blocked';
  end if;
  if within_limits and v_day_req_limit > 0 and used_day_reqs >= v_day_req_limit then
    within_limits := false;
    limit_reason := 'daily_request_limit_reached';
    limit_window := 'daily';
    limit_metric := 'requests';
    current_value := used_day_reqs;
    limit_value := v_day_req_limit;
    limit_reset_at := day_start + interval '1 day';
  end if;
  if within_limits and v_wk_req_limit > 0 and used_wk_reqs >= v_wk_req_limit then
    within_limits := false;
    limit_reason := 'weekly_request_limit_reached';
    limit_window := 'weekly';
    limit_metric := 'requests';
    current_value := used_wk_reqs;
    limit_value := v_wk_req_limit;
    limit_reset_at := week_start + interval '1 week';
  end if;
  if within_limits and v_mo_req_limit > 0 and used_mo_reqs >= v_mo_req_limit then
    within_limits := false;
    limit_reason := 'monthly_request_limit_reached';
    limit_window := 'monthly';
    limit_metric := 'requests';
    current_value := used_mo_reqs;
    limit_value := v_mo_req_limit;
    limit_reset_at := month_start + interval '1 month';
  end if;
  if within_limits and v_day_cost_limit > 0 and used_day_cost >= v_day_cost_limit then
    within_limits := false;
    limit_reason := 'daily_cost_limit_reached';
    limit_window := 'daily';
    limit_metric := 'cost';
    current_value := used_day_cost;
    limit_value := v_day_cost_limit;
    limit_reset_at := day_start + interval '1 day';
  end if;
  if within_limits and v_wk_cost_limit > 0 and used_wk_cost >= v_wk_cost_limit then
    within_limits := false;
    limit_reason := 'weekly_cost_limit_reached';
    limit_window := 'weekly';
    limit_metric := 'cost';
    current_value := used_wk_cost;
    limit_value := v_wk_cost_limit;
    limit_reset_at := week_start + interval '1 week';
  end if;
  if within_limits and v_mo_cost_limit > 0 and used_mo_cost >= v_mo_cost_limit then
    within_limits := false;
    limit_reason := 'monthly_cost_limit_reached';
    limit_window := 'monthly';
    limit_metric := 'cost';
    current_value := used_mo_cost;
    limit_value := v_mo_cost_limit;
    limit_reset_at := month_start + interval '1 month';
  end if;

  key_limit_status :=
    jsonb_build_object(
      'ok', within_limits,
      'reason', limit_reason,
      'limit_window', limit_window,
      'limit_metric', limit_metric,
      'current_value', current_value,
      'limit_value', limit_value,
      'reset_at', to_jsonb(limit_reset_at),
      'now', to_jsonb(now_utc),
      'buckets', jsonb_build_object(
        'daily', jsonb_build_object(
          'window_start', to_jsonb(day_start),
          'requests_used', used_day_reqs,
          'requests_limit', v_day_req_limit,
          'cost_used_nanos', used_day_cost,
          'cost_limit_nanos', v_day_cost_limit
        ),
        'weekly', jsonb_build_object(
          'window_start', to_jsonb(week_start),
          'requests_used', used_wk_reqs,
          'requests_limit', v_wk_req_limit,
          'cost_used_nanos', used_wk_cost,
          'cost_limit_nanos', v_wk_cost_limit
        ),
        'monthly', jsonb_build_object(
          'window_start', to_jsonb(month_start),
          'requests_used', used_mo_reqs,
          'requests_limit', v_mo_req_limit,
          'cost_used_nanos', used_mo_cost,
          'cost_limit_nanos', v_mo_cost_limit
        )
      )
    );

  -- ============================================================================
  -- TEAM & KEY ENRICHMENT (Wide Event Context for Observability)
  -- Purpose: Gather user/team context for comprehensive logging (loggingsucks.com pattern)
  -- ============================================================================
  -- Team metadata & wallet
  select
    t.created_at,
    coalesce(t.tier, 'basic'),
    greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0),
    coalesce(w.reserved_nanos, 0)::bigint
  into
    team_created_at,
    team_tier,
    team_balance_nanos,
    team_reserved_nanos
  from public.workspaces t
  left join public.wallets w on w.workspace_id = t.id
  where t.id = gateway_fetch_request_context.workspace_id
  limit 1;

  -- Team spend & request aggregates
  select
    count(*),
    coalesce(sum(gr.cost_nanos), 0)::bigint,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= now_utc - interval '24 hours'), 0)::bigint,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= now_utc - interval '7 days'), 0)::bigint,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= now_utc - interval '30 days'), 0)::bigint,
    count(*) filter (where gr.created_at >= now_utc - interval '1 hour'),
    count(*) filter (where gr.created_at >= now_utc - interval '24 hours')
  into
    team_total_requests,
    team_total_spend_nanos,
    team_spend_24h_nanos,
    team_spend_7d_nanos,
    team_spend_30d_nanos,
    team_requests_1h,
    team_requests_24h
  from public.gateway_requests gr
  where gr.workspace_id = gateway_fetch_request_context.workspace_id
    and gr.success is true;

  -- Calculate tier using calendar-month qualification + lock-window grace.
  -- Function maintains team tier/counters in database when state changes.
  team_tier := calculate_tier_with_grace(gateway_fetch_request_context.workspace_id, team_spend_30d_nanos);

  team_enrichment := jsonb_build_object(
    'tier', team_tier,
    'created_at', to_jsonb(team_created_at),
    'account_age_days', extract(epoch from (now_utc - team_created_at)) / 86400,
    'balance_nanos', team_balance_nanos,
    'available_nanos', team_balance_nanos,
    'reserved_nanos', team_reserved_nanos,
    'balance_usd', round((team_balance_nanos::numeric / 1000000000.0)::numeric, 2),
    'balance_is_low', team_balance_nanos < min_balance_nanos,
    'total_requests', team_total_requests,
    'total_spend_nanos', team_total_spend_nanos,
    'total_spend_usd', round((team_total_spend_nanos::numeric / 1000000000.0)::numeric, 2),
    'spend_24h_nanos', team_spend_24h_nanos,
    'spend_24h_usd', round((team_spend_24h_nanos::numeric / 1000000000.0)::numeric, 4),
    'spend_7d_nanos', team_spend_7d_nanos,
    'spend_7d_usd', round((team_spend_7d_nanos::numeric / 1000000000.0)::numeric, 2),
    'spend_30d_nanos', team_spend_30d_nanos,
    'spend_30d_usd', round((team_spend_30d_nanos::numeric / 1000000000.0)::numeric, 2),
    'requests_1h', team_requests_1h,
    'requests_24h', team_requests_24h
  );

  -- Key metadata & aggregates
  select
    k.name,
    k.created_at
  into
    key_name,
    key_created_at
  from public.keys k
  where k.id = gateway_fetch_request_context.api_key_id
  limit 1;

  select
    count(*),
    coalesce(sum(gr.cost_nanos), 0)::bigint
  into
    key_total_requests,
    key_total_spend_nanos
  from public.gateway_requests gr
  where gr.key_id = gateway_fetch_request_context.api_key_id
    and gr.success is true;

  key_enrichment := jsonb_build_object(
    'name', key_name,
    'created_at', to_jsonb(key_created_at),
    'key_age_days', extract(epoch from (now_utc - key_created_at)) / 86400,
    'total_requests', key_total_requests,
    'total_spend_nanos', key_total_spend_nanos,
    'total_spend_usd', round((key_total_spend_nanos::numeric / 1000000000.0)::numeric, 2),
    'requests_today', used_day_reqs,
    'spend_today_nanos', used_day_cost,
    'spend_today_usd', round((used_day_cost::numeric / 1000000000.0)::numeric, 4),
    'daily_limit_pct', case
      when v_day_req_limit > 0 then round((used_day_reqs::numeric / v_day_req_limit::numeric * 100)::numeric, 1)
      else null
    end
  );

  -- provider candidates (BYOK) + pricing, fully qualifying params
  with provider_rows as (
    select distinct on (m.provider_api_model_id)
      m.provider_api_model_id,
      m.provider_id,
      m.api_model_id,
      m.provider_model_slug, coalesce((select route.metadata -> 'availability' from public.v2_model_provider_routes route where route.provider_model_id = m.provider_api_model_id), p.metadata -> 'availability') as availability,
      m.routing_status as model_status,
      m.input_modalities,
      m.output_modalities,
      p.prompt_training_policy,
      p.data_policy_tier,
      p.data_policy_confidence,
      p.data_policy_contract_mode,
	  p.data_policy_variant,
      c.status as capability_status,
      c.params as capability_params,
      c.max_input_tokens,
      c.max_output_tokens
    from (select provider_model_id as provider_api_model_id, provider_slug as provider_id, model_slug as api_model_id, model_slug as model_id, provider_model_slug, routing_enabled as is_active_gateway, status as routing_status, input_modalities, output_modalities, context_length, max_output_tokens, effective_from, effective_to, created_at, updated_at from public.v2_model_provider_routes) m
    join (select model_slug as model_id, lab_slug as organisation_id, name, description, status, hidden, announced_at as announcement_date, released_at as release_date, deprecated_at as deprecation_date, retired_at as retirement_date, previous_model_slug as previous_model_id, input_modalities as input_types, output_modalities as output_types, metadata, created_at, updated_at from public.v2_models) dm
      on dm.model_id = coalesce(m.model_id, m.api_model_id)
    join public.v2_providers p
      on p.provider_slug = m.provider_id
    join (select provider_model_id as provider_api_model_id, capability_id, status, params, max_input_tokens, max_output_tokens, effective_from, effective_to, created_at, updated_at from public.v2_route_capabilities) c
      on c.provider_api_model_id = m.provider_api_model_id
    where m.api_model_id = resolved_model
      and coalesce(dm.hidden, false) = false
      and (dm.status is null or lower(dm.status) in ('active', 'available', 'deprecated'))
      and (dm.retirement_date is null or dm.retirement_date > now() at time zone 'utc')
      and c.capability_id = gateway_fetch_request_context.endpoint
      and c.status in ('active', 'deranked', 'deranked_lvl1', 'deranked_lvl2', 'deranked_lvl3')
      and m.is_active_gateway
      and (m.effective_from is null or m.effective_from <= now() at time zone 'utc')
      and (m.effective_to   is null or (now() at time zone 'utc') < m.effective_to)
    order by m.provider_api_model_id, coalesce(c.updated_at, c.created_at) desc
  )
  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'provider_id', pr.provider_id,
          'api_model_id', pr.api_model_id,
          'pricing_key', pr.provider_id,
          'provider_model_slug', pr.provider_model_slug, 'availability', pr.availability,
          'model_status', pr.model_status,
          'input_modalities', pr.input_modalities,
          'output_modalities', pr.output_modalities,
          'prompt_training_policy', coalesce(pr.prompt_training_policy, 'unknown'),
          'data_policy_tier', coalesce(pr.data_policy_tier, 'unknown'),
          'data_policy_confidence', coalesce(pr.data_policy_confidence, 'unknown'),
          'data_policy_contract_mode', coalesce(pr.data_policy_contract_mode, 'none'),
		  'data_policy_variant', coalesce(pr.data_policy_variant, 'standard'),
          'capability_status', pr.capability_status,
          'capability_params', coalesce(pr.capability_params, '{}'::jsonb),
          'max_input_tokens', pr.max_input_tokens,
          'max_output_tokens', pr.max_output_tokens,
          'supports_endpoint', true,
          'base_weight', 1,
          'byok_meta', coalesce((
            select jsonb_agg(
              jsonb_build_object(
                'provider_id', bk.provider_id,
                'id', bk.id,
                'name', bk.name,
                'fingerprint_sha256', bk.fingerprint_sha256,
                'key_version', bk.key_version,
                'always_use', bk.always_use
              )
            )
            from public.byok_keys bk
            where bk.workspace_id    = gateway_fetch_request_context.workspace_id
              and bk.provider_id = pr.provider_id
              and bk.enabled     = true
          ), '[]'::jsonb)
        )
      ), '[]'::jsonb
    ) as provider_payload,
    coalesce(
      jsonb_object_agg(
        pr.provider_id,
        (
          with rules as (
            select r.*
            from (select meter.sku_meter_id::text as rule_id, route.provider_slug as provider_id, route.model_slug as api_model_id, route.provider_slug || ':' || route.model_slug || ':' || sku.operation as model_key, sku.operation as capability_id, coalesce(sku.service_tier_slug, 'standard') as pricing_plan, meter.meter_key as meter, meter.unit, meter.unit_quantity as unit_size, meter.price_nanos / 1000000000.0 as price_per_unit, coalesce(nullif(meter.metadata->>'included_quantity', '')::numeric, nullif(sku.metadata->>'included_quantity', '')::numeric, 0) as included_quantity, sku.currency, coalesce(nullif(meter.metadata->>'priority', '')::integer, meter.meter_order, 100) as priority, sku.effective_from, sku.effective_to, coalesce(sku.metadata->'match', meter.metadata->'match', '[]'::jsonb) as match, coalesce(sku.metadata->>'billing_timestamp_basis', 'request_start') as billing_timestamp_basis, coalesce(sku.metadata->'time_windows', '[]'::jsonb) as time_windows, greatest(sku.updated_at, meter.updated_at) as updated_at from public.v2_pricing_skus sku join public.v2_model_provider_routes route on route.provider_model_id = sku.provider_model_id join public.v2_pricing_sku_meters meter on meter.sku_id = sku.sku_id where sku.status = 'active' and meter.billable) r
            -- TODO: Redesign pricing selection to key on provider_api_model_id or
            -- explicit variant metadata so provider-only SKUs (for example CrofAI
            -- precision tiers) can share a parent internal model without forcing
            -- distinct api_model_id values just to preserve pricing separation.
            where r.model_key =
              pr.provider_id || ':' || resolved_model || ':' || gateway_fetch_request_context.endpoint
              and r.capability_id = gateway_fetch_request_context.endpoint
              and (r.effective_from is null or r.effective_from <= now() at time zone 'utc')
              and (r.effective_to   is null or (now() at time zone 'utc') < r.effective_to)
          ),
          ordered_rules as (
            select
              jsonb_agg(
                jsonb_build_object(
                  'id', r.rule_id,
                  'pricing_plan', r.pricing_plan,
                  'meter', r.meter,
                  'unit', r.unit,
                  'unit_size', r.unit_size,
                  'price_per_unit', r.price_per_unit,
                  'included_quantity', r.included_quantity,
                  'currency', r.currency,
                  'match', r.match,
                  'priority', r.priority,
                  'billing_timestamp_basis', coalesce(r.billing_timestamp_basis, 'request_start'),
                  'time_windows', coalesce(r.time_windows, '[]'::jsonb)
                )
                order by r.priority desc, coalesce(r.effective_from, now() at time zone 'utc') desc
              ) as items,
              max(r.updated_at) as version_ts,
              min(r.effective_from) as effective_from,
              min(r.effective_to) as effective_to
            from rules r
          )
          select jsonb_build_object(
            'provider', pr.provider_id,
            'model', resolved_model,
            'endpoint', gateway_fetch_request_context.endpoint,
            'effective_from', to_jsonb(o.effective_from),
            'effective_to',   to_jsonb(o.effective_to),
            'currency', 'USD',
            'version', to_jsonb(o.version_ts),
            'rules', coalesce(o.items, '[]'::jsonb)
          )
          from ordered_rules o
        )
      ),
      '{}'::jsonb
    ) as pricing_payload
  into providers, pricing
  from provider_rows pr;

  return jsonb_build_object(
    'workspace_id', gateway_fetch_request_context.workspace_id,
    'resolved_model', resolved_model,
    'preset', preset_data,
    'key_ok', key_status,
    'key_limit_ok', key_limit_status,
    'credit_ok', credit_status,
    'providers', providers,
    'pricing', pricing,
    'team_enrichment', team_enrichment,
    'key_enrichment', key_enrichment
  );
end;

declare
  payload jsonb;
  min_balance_nanos bigint := 1000000000; -- 1.00 USD
  wallet_balance_nanos bigint := 0;
  wallet_reserved_nanos bigint := 0;
  wallet_available_nanos bigint := 0;
  credit_status jsonb;
  enriched_pricing jsonb;
begin
  payload := public.gateway_fetch_request_context(workspace_id, model, endpoint, api_key_id);
  if payload is null then
    return null;
  end if;

  with provider_cards as (
    select provider_key, card
    from jsonb_each(coalesce(payload->'pricing', '{}'::jsonb)) as p(provider_key, card)
  ),
  enriched_cards as (
    select
      provider_key,
      jsonb_set(
        card,
        '{rules}',
        coalesce(rules.enriched_rules, '[]'::jsonb),
        true
      ) as card
    from provider_cards
    cross join lateral (
      select jsonb_agg(
        rule_item.value ||
        jsonb_build_object(
          'billing_timestamp_basis', coalesce(rule_row.billing_timestamp_basis, 'request_start'),
          'time_windows', coalesce(rule_row.time_windows, '[]'::jsonb)
        )
        order by rule_item.ordinality
      ) as enriched_rules
      from jsonb_array_elements(coalesce(card->'rules', '[]'::jsonb)) with ordinality as rule_item(value, ordinality)
      left join private.v2_rpc_pricing_compat rule_row
        on rule_row.rule_id::text = rule_item.value->>'id'
    ) rules
  )
  select coalesce(jsonb_object_agg(provider_key, card), '{}'::jsonb)
  into enriched_pricing
  from enriched_cards;

  payload := jsonb_set(payload, '{pricing}', coalesce(enriched_pricing, '{}'::jsonb), true);

  select
    coalesce(w.balance_nanos, 0)::bigint,
    coalesce(w.reserved_nanos, 0)::bigint
  into
    wallet_balance_nanos,
    wallet_reserved_nanos
  from public.wallets w
  where w.workspace_id = gateway_fetch_request_context_with_reservations.workspace_id
  limit 1;

  if not found then
    credit_status := jsonb_build_object('ok', false, 'reason', 'wallet_missing');
    return jsonb_set(payload, '{credit_ok}', credit_status, true);
  end if;

  wallet_available_nanos := greatest(wallet_balance_nanos - wallet_reserved_nanos, 0);

  if wallet_available_nanos >= min_balance_nanos then
    credit_status := jsonb_build_object(
      'ok', true,
      'balance_nanos', wallet_available_nanos,
      'raw_balance_nanos', wallet_balance_nanos,
      'reserved_nanos', wallet_reserved_nanos,
      'available_nanos', wallet_available_nanos
    );
  else
    credit_status := jsonb_build_object(
      'ok', false,
      'reason', 'insufficient_funds',
      'balance_nanos', wallet_available_nanos,
      'raw_balance_nanos', wallet_balance_nanos,
      'reserved_nanos', wallet_reserved_nanos,
      'available_nanos', wallet_available_nanos
    );
  end if;

  payload := jsonb_set(payload, '{credit_ok}', credit_status, true);

  if jsonb_typeof(payload->'team_enrichment') = 'object' then
    payload := jsonb_set(payload, '{team_enrichment,balance_nanos}', to_jsonb(wallet_available_nanos), true);
    payload := jsonb_set(payload, '{team_enrichment,available_nanos}', to_jsonb(wallet_available_nanos), true);
    payload := jsonb_set(payload, '{team_enrichment,reserved_nanos}', to_jsonb(wallet_reserved_nanos), true);
    payload := jsonb_set(
      payload,
      '{team_enrichment,balance_usd}',
      to_jsonb(round((wallet_available_nanos::numeric / 1000000000.0)::numeric, 2)),
      true
    );
    payload := jsonb_set(payload, '{team_enrichment,balance_is_low}', to_jsonb(wallet_available_nanos < min_balance_nanos), true);
  end if;

  return payload;
end;

begin
  if p_status is null or p_status not in ('completed', 'failed') then
    raise exception 'invalid_batch_file_upload_status';
  end if;
  update public.gateway_batch_file_uploads
  set status = p_status,
      provider_file_id = nullif(trim(coalesce(p_provider_file_id, '')), ''),
      updated_at = now()
  where workspace_id = p_workspace_id and upload_id = p_upload_id;
end;

declare
  v_session public.gateway_realtime_sessions%rowtype;
begin
  select * into v_session
  from public.gateway_realtime_sessions
  where session_id = p_session_id
  for update;

  if not found then raise exception 'realtime_session_not_found'; end if;
  if coalesce(v_session.provider_client_secret_hash, '') <> coalesce(p_client_secret_hash, '') then
    raise exception 'realtime_relay_forbidden';
  end if;
  if v_session.status <> 'created' then
    raise exception 'realtime_relay_already_connected';
  end if;
  if v_session.expires_at is not null and v_session.expires_at <= now() then
    raise exception 'realtime_session_expired';
  end if;

  update public.gateway_realtime_sessions
  set status = 'connecting', last_event_at = now(), updated_at = now()
  where id = v_session.id and status = 'created'
  returning * into v_session;

  if not found then raise exception 'realtime_relay_already_connected'; end if;
  return next v_session;
end;

declare
  v_wallet public.wallets%rowtype;
  v_session public.gateway_realtime_sessions%rowtype;
  v_count integer;
begin
  if p_workspace_id is null or coalesce(trim(p_session_id), '') = '' then
    raise exception 'invalid_realtime_session_identity';
  end if;
  if p_key_id is null then
    raise exception 'invalid_realtime_key';
  end if;
  if p_hold_nanos is null or p_hold_nanos <= 0 then
    raise exception 'invalid_realtime_hold';
  end if;
  if p_source not in ('api', 'chat') then
    raise exception 'invalid_realtime_source';
  end if;
  if p_expires_at is null or p_expires_at <= now() then
    raise exception 'invalid_realtime_expiry';
  end if;

  -- The wallet row serializes create/limit checks for the workspace.
  select * into v_wallet
  from public.wallets
  where workspace_id = p_workspace_id
  for update;

  if not found then
    raise exception 'wallet_not_found';
  end if;

  select count(*)::integer into v_count
  from public.gateway_realtime_sessions
  where workspace_id = p_workspace_id
    and status in ('created', 'connecting', 'connected', 'ending', 'billing_unresolved');
  if v_count >= greatest(1, p_max_workspace_sessions) then
    raise exception 'realtime_workspace_concurrency_limit';
  end if;

  select count(*)::integer into v_count
  from public.gateway_realtime_sessions
  where workspace_id = p_workspace_id
    and key_id = p_key_id
    and status in ('created', 'connecting', 'connected', 'ending', 'billing_unresolved');
  if v_count >= greatest(1, p_max_key_sessions) then
    raise exception 'realtime_key_concurrency_limit';
  end if;

  if nullif(trim(coalesce(p_user_id, '')), '') is not null then
    select count(*)::integer into v_count
    from public.gateway_realtime_sessions
    where workspace_id = p_workspace_id
      and user_id = p_user_id
      and status in ('created', 'connecting', 'connected', 'ending', 'billing_unresolved');
    if v_count >= greatest(1, p_max_user_sessions) then
      raise exception 'realtime_user_concurrency_limit';
    end if;
  end if;

  select count(*)::integer into v_count
  from public.gateway_realtime_sessions
  where workspace_id = p_workspace_id
    and created_at >= now() - interval '1 minute';
  if v_count >= greatest(1, p_max_creations_per_minute) then
    raise exception 'realtime_creation_rate_limit';
  end if;

  if coalesce(v_wallet.balance_nanos, 0) - coalesce(v_wallet.reserved_nanos, 0) < p_hold_nanos then
    raise exception 'insufficient_funds';
  end if;

  insert into public.gateway_realtime_sessions (
    session_id, workspace_id, key_id, user_id, source, provider, model_id,
    provider_model_id, voice, status, expires_at, reservation_prefix,
    reservation_count, reserved_nanos, provider_client_secret_hash, metadata
  ) values (
    p_session_id, p_workspace_id, p_key_id, nullif(trim(coalesce(p_user_id, '')), ''),
    p_source, p_provider, p_model_id, p_provider_model_id, p_voice, 'created',
    p_expires_at, p_reservation_prefix, 1, p_hold_nanos,
    p_client_secret_hash, coalesce(p_metadata, '{}'::jsonb)
  ) returning * into v_session;

  insert into public.gateway_wallet_reservations (
    reservation_id, workspace_id, amount_nanos, status, hold_ref_id,
    captured_nanos, released_nanos, created_at, updated_at
  ) values (
    p_reservation_id, p_workspace_id, p_hold_nanos, 'reserved', p_session_id,
    0, 0, now(), now()
  );

  insert into public.gateway_requests (
    workspace_id, request_id, realtime_session_id, endpoint, model_id, provider,
    stream, byok, status_code, success, usage, cost_nanos, currency,
    pricing_lines, key_id, created_at
  ) values (
    p_workspace_id, 'realtime:' || p_session_id, p_session_id, 'audio.realtime',
    p_model_id, p_provider, true, false, 102, false, '{}'::jsonb, 0, 'USD',
    '[]'::jsonb, p_key_id, v_session.started_at
  );

  update public.wallets
  set reserved_nanos = coalesce(reserved_nanos, 0) + p_hold_nanos,
      updated_at = now()
  where workspace_id = p_workspace_id;

  return next v_session;
end;

declare
  v_provider text := lower(trim(coalesce(new.provider, '')));
  v_active_count integer;
begin
  if v_provider = '' then
    raise exception 'realtime_provider_required';
  end if;

  -- Serialize creates for one shared provider account across all workspaces.
  perform pg_advisory_xact_lock(
    hashtextextended('gateway_realtime_provider:' || v_provider, 0)
  );

  select count(*)::integer into v_active_count
  from public.gateway_realtime_sessions
  where lower(provider) = v_provider
    and status in ('created', 'connecting', 'connected', 'ending');

  if v_active_count >= 20 then
    raise exception 'realtime_provider_concurrency_limit';
  end if;

  return new;
end;

declare
  v_wallet public.wallets%rowtype;
  v_session public.gateway_realtime_sessions%rowtype;
  v_additional bigint;
begin
  select * into v_wallet
  from public.wallets
  where workspace_id = p_workspace_id
  for update;
  if not found then raise exception 'wallet_not_found'; end if;

  select * into v_session
  from public.gateway_realtime_sessions
  where workspace_id = p_workspace_id and session_id = p_session_id
  for update;
  if not found then raise exception 'realtime_session_not_found'; end if;
  if v_session.status not in ('created', 'connected', 'ending') then
    raise exception 'realtime_session_terminal';
  end if;

  v_additional := greatest(0, coalesce(p_target_reserved_nanos, 0) - coalesce(v_session.reserved_nanos, 0));
  if v_additional > 0 then
    if coalesce(v_wallet.balance_nanos, 0) - coalesce(v_wallet.reserved_nanos, 0) < v_additional then
      update public.gateway_realtime_sessions
      set status = 'ending', disconnect_reason = 'credit_hold_extension_failed',
          error_code = 'insufficient_funds', updated_at = now()
      where id = v_session.id;
      raise exception 'insufficient_funds';
    end if;

    insert into public.gateway_wallet_reservations (
      reservation_id, workspace_id, amount_nanos, status, hold_ref_id,
      captured_nanos, released_nanos, created_at, updated_at
    ) values (
      p_reservation_id, p_workspace_id, v_additional, 'reserved', p_session_id,
      0, 0, now(), now()
    );
    update public.wallets
    set reserved_nanos = coalesce(reserved_nanos, 0) + v_additional,
        updated_at = now()
    where workspace_id = p_workspace_id;
  end if;

  update public.gateway_realtime_sessions
  set reservation_count = reservation_count + case when v_additional > 0 then 1 else 0 end,
      reserved_nanos = reserved_nanos + v_additional,
      estimated_cost_nanos = greatest(estimated_cost_nanos, coalesce(p_estimated_cost_nanos, 0)),
      last_event_at = now(), updated_at = now()
  where id = v_session.id
  returning * into v_session;

  return next v_session;
end;

declare
  v_session public.gateway_realtime_sessions%rowtype;
begin
  update public.gateway_realtime_sessions
  set status = 'billing_unresolved',
      usage = coalesce(p_usage, '{}'::jsonb),
      disconnect_reason = left(coalesce(nullif(trim(p_reason), ''), 'authoritative_usage_missing'), 240),
      error_code = 'realtime_authoritative_usage_missing',
      last_event_at = now(),
      updated_at = now()
  where workspace_id = p_workspace_id
    and session_id = p_session_id
    and status in ('created', 'connecting', 'connected', 'ending', 'billing_unresolved')
  returning * into v_session;

  if not found then
    select * into v_session
    from public.gateway_realtime_sessions
    where workspace_id = p_workspace_id and session_id = p_session_id;
  end if;
  if not found then raise exception 'realtime_session_not_found'; end if;
  if v_session.status in ('completed', 'failed', 'cancelled', 'expired') then
    return next v_session;
    return;
  end if;

  update public.gateway_requests
  set status_code = 202,
      success = false,
      error_code = 'realtime_authoritative_usage_missing',
      error_message = 'Realtime billing requires reconciliation.',
      usage = coalesce(p_usage, '{}'::jsonb)
  where realtime_session_id = p_session_id
    and created_at = v_session.started_at;

  return next v_session;
end;

declare
  v_session public.gateway_realtime_sessions%rowtype;
  v_wallet public.wallets%rowtype;
  v_reservation public.gateway_wallet_reservations%rowtype;
  v_cost bigint := greatest(0, coalesce(p_final_cost_nanos, 0));
  v_held bigint := 0;
  v_capture_remaining bigint;
  v_row_capture bigint;
  v_before_balance bigint;
  v_before_reserved bigint;
  v_request_count integer;
  v_next_status text := lower(coalesce(nullif(trim(p_status), ''), 'completed'));
begin
  if v_next_status not in ('completed', 'failed', 'cancelled', 'expired') then
    raise exception 'invalid_realtime_terminal_status';
  end if;

  select * into v_session from public.gateway_realtime_sessions
  where workspace_id = p_workspace_id and session_id = p_session_id;
  if not found then
    return query select false, false, 'not_found'::text, 0::bigint, 0::bigint,
      0::bigint, 0::bigint, null::bigint, null::bigint, null::bigint, null::bigint;
    return;
  end if;
  if v_session.status in ('completed', 'failed', 'cancelled', 'expired') then
    return query select false, true, v_session.status, coalesce(v_session.final_cost_nanos, 0),
      v_session.reserved_nanos, v_session.captured_nanos, v_session.released_nanos,
      null::bigint, null::bigint, null::bigint, null::bigint;
    return;
  end if;

  perform 1 from public.gateway_wallet_reservations gwr
  where gwr.workspace_id = p_workspace_id and gwr.status in ('held', 'reserved')
    and (gwr.hold_ref_id = p_session_id or gwr.reservation_id like v_session.reservation_prefix || '%')
  order by gwr.created_at, gwr.reservation_id
  for update;

  select * into v_wallet from public.wallets
  where workspace_id = p_workspace_id for update;
  if not found then raise exception 'wallet_not_found'; end if;

  select * into v_session from public.gateway_realtime_sessions
  where workspace_id = p_workspace_id and session_id = p_session_id for update;
  if v_session.status in ('completed', 'failed', 'cancelled', 'expired') then
    return query select false, true, v_session.status, coalesce(v_session.final_cost_nanos, 0),
      v_session.reserved_nanos, v_session.captured_nanos, v_session.released_nanos,
      null::bigint, null::bigint, null::bigint, null::bigint;
    return;
  end if;

  select coalesce(sum(gwr.amount_nanos), 0)::bigint into v_held
  from public.gateway_wallet_reservations gwr
  where gwr.workspace_id = p_workspace_id and gwr.status in ('held', 'reserved')
    and (gwr.hold_ref_id = p_session_id or gwr.reservation_id like v_session.reservation_prefix || '%');

  v_before_balance := coalesce(v_wallet.balance_nanos, 0);
  v_before_reserved := coalesce(v_wallet.reserved_nanos, 0);
  if v_before_reserved < v_held then
    return query select false, false, 'reserved_balance_mismatch'::text, v_cost, v_held,
      0::bigint, v_held, v_before_balance, v_before_balance, v_before_reserved, v_before_reserved;
    return;
  end if;
  if v_cost > v_held + greatest(0, v_before_balance - v_before_reserved) then
    return query select false, false, 'insufficient_unreserved_balance'::text, v_cost, v_held,
      0::bigint, v_held, v_before_balance, v_before_balance, v_before_reserved, v_before_reserved;
    return;
  end if;

  update public.wallets w
  set balance_nanos = w.balance_nanos - v_cost,
      reserved_nanos = w.reserved_nanos - v_held,
      updated_at = now()
  where workspace_id = p_workspace_id;

  v_capture_remaining := least(v_cost, v_held);
  for v_reservation in
    select gwr.* from public.gateway_wallet_reservations gwr
    where gwr.workspace_id = p_workspace_id and gwr.status in ('held', 'reserved')
      and (gwr.hold_ref_id = p_session_id or gwr.reservation_id like v_session.reservation_prefix || '%')
    order by gwr.created_at, gwr.reservation_id
    for update
  loop
    v_row_capture := least(v_reservation.amount_nanos, v_capture_remaining);
    update public.gateway_wallet_reservations
    set status = case when v_row_capture > 0 then 'captured' else 'released' end,
        captured_nanos = v_row_capture,
        released_nanos = v_reservation.amount_nanos - v_row_capture,
        capture_ref_id = case when v_row_capture > 0 then p_session_id else null end,
        release_ref_id = case when v_row_capture < v_reservation.amount_nanos then p_session_id else null end,
        captured_at = case when v_row_capture > 0 then now() else null end,
        released_at = case when v_row_capture < v_reservation.amount_nanos then now() else null end,
        updated_at = now()
    where workspace_id = p_workspace_id and reservation_id = v_reservation.reservation_id;
    v_capture_remaining := greatest(0, v_capture_remaining - v_row_capture);
  end loop;

  if v_cost > 0 then
    insert into public.credit_ledger (
      workspace_id, event_time, kind, amount_nanos, before_balance_nanos,
      after_balance_nanos, before_reserved_nanos, after_reserved_nanos,
      ref_type, ref_id, created_at, status
    ) values (
      p_workspace_id, now(), 'charge', -v_cost, v_before_balance,
      v_before_balance - v_cost, v_before_reserved, v_before_reserved - v_held,
      'realtime_session', p_session_id, now(), 'captured'
    ) on conflict (ref_type, ref_id) do nothing;
  end if;

  update public.gateway_realtime_sessions
  set status = v_next_status,
      ended_at = coalesce(ended_at, now()),
      final_cost_nanos = v_cost,
      captured_nanos = v_cost,
      released_nanos = greatest(0, v_held - least(v_cost, v_held)),
      reserved_nanos = v_held,
      usage = coalesce(p_usage, '{}'::jsonb),
      pricing_lines = case when jsonb_typeof(coalesce(p_pricing_lines, '[]'::jsonb)) = 'array'
        then p_pricing_lines else '[]'::jsonb end,
      disconnect_reason = nullif(trim(coalesce(p_disconnect_reason, '')), ''),
      error_code = nullif(trim(coalesce(p_error_code, '')), ''),
      error_message = nullif(trim(coalesce(p_error_message, '')), ''),
      updated_at = now()
  where id = v_session.id
  returning * into v_session;

  update public.gateway_requests
  set native_response_id = coalesce(v_session.provider_session_id, v_session.provider_native_id),
      status_code = case when v_next_status = 'completed' then 200 else 499 end,
      success = v_next_status = 'completed',
      error_code = nullif(trim(coalesce(p_error_code, '')), ''),
      error_message = nullif(trim(coalesce(p_error_message, '')), ''),
      generation_ms = greatest(0, floor(extract(epoch from (v_session.ended_at - v_session.started_at)) * 1000))::integer,
      usage = coalesce(p_usage, '{}'::jsonb),
      cost_nanos = v_cost,
      currency = 'USD',
      pricing_lines = case when jsonb_typeof(coalesce(p_pricing_lines, '[]'::jsonb)) = 'array'
        then p_pricing_lines else '[]'::jsonb end
  where realtime_session_id = p_session_id
    and created_at = v_session.started_at;
  get diagnostics v_request_count = row_count;
  if v_request_count <> 1 then
    raise exception 'realtime_request_summary_missing';
  end if;

  return query select true, false, v_session.status, v_cost, v_held, v_cost,
    greatest(0, v_held - least(v_cost, v_held)), v_before_balance,
    v_before_balance - v_cost, v_before_reserved, v_before_reserved - v_held;
end;

declare
  v_key_name text;
  v_chat_app_key constant text := 'https://ai-stats.phaseo.app/chat';
  v_app_id uuid;
begin
  if new.app_id is not null then
    return new;
  end if;

  if new.workspace_id is null or new.key_id is null then
    return new;
  end if;

  select k.name into v_key_name
  from public.keys k
  where k.id = new.key_id
  limit 1;

  if coalesce(v_key_name, '') <> '__chat_route_managed_key__' then
    return new;
  end if;

  insert into public.api_apps (
    workspace_id,
    app_key,
    title,
    url,
    is_active,
    last_seen,
    updated_at,
    meta
  )
  values (
    new.workspace_id,
    v_chat_app_key,
    'AI Stats Chat',
    v_chat_app_key,
    true,
    coalesce(new.created_at, now()),
    now(),
    jsonb_build_object(
      'identityUrl', v_chat_app_key,
      'managed', true
    )
  )
  on conflict (workspace_id, app_key) do update
    set title = excluded.title,
        url = excluded.url,
        is_active = true,
        last_seen = greatest(public.api_apps.last_seen, excluded.last_seen),
        updated_at = now(),
        meta = coalesce(public.api_apps.meta, '{}'::jsonb) || excluded.meta
  returning id into v_app_id;

  new.app_id := v_app_id;
  return new;
end;

declare
  v_key text;
  v_part text;
  v_cursor jsonb;
  v_value text;
begin
  if p_usage is null then
    return null;
  end if;

  foreach v_key in array p_keys loop
    v_cursor := p_usage;

    foreach v_part in array string_to_array(v_key, '.') loop
      if v_cursor is null or jsonb_typeof(v_cursor) <> 'object' or not (v_cursor ? v_part) then
        v_cursor := null;
        exit;
      end if;
      v_cursor := v_cursor -> v_part;
    end loop;

    if v_cursor is null then
      continue;
    end if;

    v_value := trim(both '"' from v_cursor::text);
    if v_value ~ '^-?[0-9]+(\.[0-9]+)?$' then
      return v_value::numeric;
    end if;
  end loop;

  return null;
end;

declare
  v_wallet public.wallets%rowtype;
  v_existing public.gateway_wallet_reservations%rowtype;
  v_amount bigint;
begin
  if p_workspace_id is null then
    raise exception 'workspace_id_required' using errcode = 'P0001';
  end if;
  if coalesce(trim(p_reservation_id), '') = '' then
    raise exception 'reservation_id_required' using errcode = 'P0001';
  end if;

  select * into v_existing
  from public.gateway_wallet_reservations
  where reservation_id = p_reservation_id
    and workspace_id = p_workspace_id
  for update;

  if not found then
    return query select false, false, 'reservation_not_found'::text, null::bigint,
      null::bigint, null::bigint, null::bigint, null::bigint;
    return;
  end if;

  select * into v_wallet
  from public.wallets
  where workspace_id = p_workspace_id
  for update;

  if not found then
    return query select false, false, 'wallet_not_found'::text, v_existing.amount_nanos,
      null::bigint, null::bigint, null::bigint, null::bigint;
    return;
  end if;

  if v_existing.status = 'captured' then
    return query select true, false, 'already_captured'::text, v_existing.amount_nanos,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint;
    return;
  end if;

  if v_existing.status <> 'reserved' then
    return query select false, false, 'reservation_not_active'::text, v_existing.amount_nanos,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint;
    return;
  end if;

  v_amount := v_existing.amount_nanos;

  if coalesce(v_wallet.reserved_nanos, 0) < v_amount then
    return query select false, false, 'reserved_balance_mismatch'::text, v_amount,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint;
    return;
  end if;

  update public.wallets
  set balance_nanos = coalesce(balance_nanos, 0) - v_amount,
      reserved_nanos = coalesce(reserved_nanos, 0) - v_amount,
      updated_at = now()
  where workspace_id = p_workspace_id
  returning *
  into v_wallet;

  update public.gateway_wallet_reservations
  set status = 'captured',
      capture_ref_id = nullif(trim(coalesce(p_capture_ref_id, '')), ''),
      captured_at = now(),
      updated_at = now()
  where reservation_id = p_reservation_id
    and workspace_id = p_workspace_id;

  return query select true, true, null::text, v_amount,
    coalesce(v_wallet.balance_nanos, 0) + v_amount,
    coalesce(v_wallet.balance_nanos, 0),
    coalesce(v_wallet.reserved_nanos, 0) + v_amount,
    coalesce(v_wallet.reserved_nanos, 0);
end;

declare
  v_wallet public.wallets%rowtype;
  v_existing public.gateway_wallet_reservations%rowtype;
  v_amount bigint;
begin
  if p_workspace_id is null then
    raise exception 'workspace_id_required' using errcode = 'P0001';
  end if;
  if coalesce(trim(p_reservation_id), '') = '' then
    raise exception 'reservation_id_required' using errcode = 'P0001';
  end if;

  select * into v_existing
  from public.gateway_wallet_reservations
  where reservation_id = p_reservation_id
    and workspace_id = p_workspace_id
  for update;

  if not found then
    return query select false, false, 'reservation_not_found'::text, null::bigint,
      null::bigint, null::bigint, null::bigint, null::bigint;
    return;
  end if;

  select * into v_wallet
  from public.wallets
  where workspace_id = p_workspace_id
  for update;

  if not found then
    return query select false, false, 'wallet_not_found'::text, v_existing.amount_nanos,
      null::bigint, null::bigint, null::bigint, null::bigint;
    return;
  end if;

  if v_existing.status = 'released' then
    return query select true, false, 'already_released'::text, v_existing.amount_nanos,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint;
    return;
  end if;

  if v_existing.status <> 'reserved' then
    return query select false, false, 'reservation_not_active'::text, v_existing.amount_nanos,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint;
    return;
  end if;

  v_amount := v_existing.amount_nanos;

  if coalesce(v_wallet.reserved_nanos, 0) < v_amount then
    return query select false, false, 'reserved_balance_mismatch'::text, v_amount,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint;
    return;
  end if;

  update public.wallets
  set reserved_nanos = coalesce(reserved_nanos, 0) - v_amount,
      updated_at = now()
  where workspace_id = p_workspace_id
  returning *
  into v_wallet;

  update public.gateway_wallet_reservations
  set status = 'released',
      release_ref_id = nullif(trim(coalesce(p_release_ref_id, '')), ''),
      released_at = now(),
      updated_at = now()
  where reservation_id = p_reservation_id
    and workspace_id = p_workspace_id;

  return query select true, true, null::text, v_amount,
    coalesce(v_wallet.balance_nanos, 0),
    coalesce(v_wallet.balance_nanos, 0),
    coalesce(v_wallet.reserved_nanos, 0) + v_amount,
    coalesce(v_wallet.reserved_nanos, 0);
end;

declare
  v_wallet public.wallets%rowtype;
  v_existing public.gateway_wallet_reservations%rowtype;
  v_key public.keys%rowtype;
  v_available bigint;
  v_before_balance bigint;
  v_before_reserved bigint;
  v_day_start timestamptz := (date_trunc('day', now() at time zone 'utc') at time zone 'utc');
  v_week_start timestamptz := (date_trunc('week', now() at time zone 'utc') at time zone 'utc');
  v_month_start timestamptz := (date_trunc('month', now() at time zone 'utc') at time zone 'utc');
  v_day_requests bigint := 0;
  v_week_requests bigint := 0;
  v_month_requests bigint := 0;
  v_day_cost bigint := 0;
  v_week_cost bigint := 0;
  v_month_cost bigint := 0;
  v_requested_count integer := greatest(0, coalesce(p_request_count, 0));
begin
  if p_workspace_id is null or coalesce(trim(p_reservation_id), '') = '' then
    raise exception 'invalid_reservation_identity';
  end if;
  if p_amount_nanos is null or p_amount_nanos <= 0 then
    raise exception 'invalid_reservation_amount';
  end if;
  if p_key_id is not null and v_requested_count <= 0 then
    raise exception 'batch_request_count_required';
  end if;
  if v_requested_count > 10000 then
    raise exception 'batch_request_limit_exceeded';
  end if;

  select * into v_existing
  from public.gateway_wallet_reservations
  where workspace_id = p_workspace_id and reservation_id = p_reservation_id
  for update;
  if found then
    select * into v_wallet from public.wallets
    where workspace_id = p_workspace_id for update;
    if not found then
      return query select false, false, 'wallet_not_found'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;
    if v_existing.amount_nanos <> p_amount_nanos
      or v_existing.key_id is distinct from p_key_id
      or coalesce(v_existing.request_count, 0) <> v_requested_count then
      raise exception 'reservation_identity_mismatch';
    end if;
    if v_existing.status in ('held', 'reserved') then
      return query select true, false, 'already_reserved'::text, v_existing.amount_nanos,
        coalesce(v_wallet.balance_nanos, 0), coalesce(v_wallet.balance_nanos, 0),
        coalesce(v_wallet.reserved_nanos, 0), coalesce(v_wallet.reserved_nanos, 0);
      return;
    end if;
    return query select false, false, 'reservation_not_active'::text, v_existing.amount_nanos,
      coalesce(v_wallet.balance_nanos, 0), coalesce(v_wallet.balance_nanos, 0),
      coalesce(v_wallet.reserved_nanos, 0), coalesce(v_wallet.reserved_nanos, 0);
    return;
  end if;

  if p_key_id is not null then
    select * into v_key from public.keys where id = p_key_id for update;
    if not found then
      return query select false, false, 'key_not_found'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;
    if v_key.workspace_id <> p_workspace_id then
      return query select false, false, 'key_wrong_workspace'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;
    if v_key.status <> 'active' or (v_key.expires_at is not null and v_key.expires_at <= now()) then
      return query select false, false, 'key_not_active'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;
    if coalesce(v_key.soft_blocked, false) then
      return query select false, false, 'key_limit_soft_blocked'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;

    select
      count(*) filter (where created_at >= v_day_start),
      count(*) filter (where created_at >= v_week_start),
      count(*) filter (where created_at >= v_month_start),
      coalesce(sum(cost_nanos) filter (where created_at >= v_day_start), 0),
      coalesce(sum(cost_nanos) filter (where created_at >= v_week_start), 0),
      coalesce(sum(cost_nanos) filter (where created_at >= v_month_start), 0)
    into v_day_requests, v_week_requests, v_month_requests,
      v_day_cost, v_week_cost, v_month_cost
    from public.gateway_requests
    where workspace_id = p_workspace_id and key_id = p_key_id and success is true;

    if coalesce(v_key.daily_limit_requests, 0) > 0
      and v_day_requests + v_requested_count > v_key.daily_limit_requests then
      return query select false, false, 'daily_request_limit_reached'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;
    if coalesce(v_key.weekly_limit_requests, 0) > 0
      and v_week_requests + v_requested_count > v_key.weekly_limit_requests then
      return query select false, false, 'weekly_request_limit_reached'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;
    if coalesce(v_key.monthly_limit_requests, 0) > 0
      and v_month_requests + v_requested_count > v_key.monthly_limit_requests then
      return query select false, false, 'monthly_request_limit_reached'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;
    if coalesce(v_key.daily_limit_cost_nanos, 0) > 0
      and v_day_cost + p_amount_nanos > v_key.daily_limit_cost_nanos then
      return query select false, false, 'daily_cost_limit_reached'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;
    if coalesce(v_key.weekly_limit_cost_nanos, 0) > 0
      and v_week_cost + p_amount_nanos > v_key.weekly_limit_cost_nanos then
      return query select false, false, 'weekly_cost_limit_reached'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;
    if coalesce(v_key.monthly_limit_cost_nanos, 0) > 0
      and v_month_cost + p_amount_nanos > v_key.monthly_limit_cost_nanos then
      return query select false, false, 'monthly_cost_limit_reached'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;
  end if;

  select * into v_wallet from public.wallets
  where workspace_id = p_workspace_id for update;
  if not found then
    return query select false, false, 'wallet_not_found'::text, p_amount_nanos,
      null::bigint, null::bigint, null::bigint, null::bigint;
    return;
  end if;
  v_available := coalesce(v_wallet.balance_nanos, 0) - coalesce(v_wallet.reserved_nanos, 0);
  if v_available < p_amount_nanos then
    return query select false, false, 'insufficient_balance'::text, p_amount_nanos,
      coalesce(v_wallet.balance_nanos, 0), coalesce(v_wallet.balance_nanos, 0),
      coalesce(v_wallet.reserved_nanos, 0), coalesce(v_wallet.reserved_nanos, 0);
    return;
  end if;

  insert into public.gateway_wallet_reservations (
    reservation_id, workspace_id, amount_nanos, status, hold_ref_id,
    key_id, request_count, created_at, updated_at
  ) values (
    p_reservation_id, p_workspace_id, p_amount_nanos, 'reserved',
    nullif(trim(coalesce(p_hold_ref_id, '')), ''), p_key_id,
    nullif(v_requested_count, 0), now(), now()
  );

  v_before_balance := coalesce(v_wallet.balance_nanos, 0);
  v_before_reserved := coalesce(v_wallet.reserved_nanos, 0);
  update public.wallets
  set reserved_nanos = v_before_reserved + p_amount_nanos, updated_at = now()
  where workspace_id = p_workspace_id
  returning * into v_wallet;

  if p_key_id is not null then
    insert into public.gateway_requests (
      workspace_id, request_id, endpoint, model_id, provider,
      status_code, success, usage, cost_nanos, currency, key_id
    )
    select
      p_workspace_id,
      'batch_hold_usage:' || p_reservation_id || ':' || item::text,
      'batch',
      'batch/reserved',
      null,
      202,
      true,
      jsonb_build_object('batch_reserved', true),
      (p_amount_nanos / v_requested_count)
        + case when item <= (p_amount_nanos % v_requested_count) then 1 else 0 end,
      'USD',
      p_key_id
    from generate_series(1, v_requested_count) as item
    ;
  end if;

  return query select true, true, null::text, p_amount_nanos,
    v_before_balance, coalesce(v_wallet.balance_nanos, 0),
    v_before_reserved, coalesce(v_wallet.reserved_nanos, 0);
end;

declare
  v_wallet public.wallets%rowtype;
  v_reservation public.gateway_wallet_reservations%rowtype;
  v_before_balance bigint;
  v_before_reserved bigint;
  v_available_for_settlement bigint;
begin
  if p_workspace_id is null or coalesce(trim(p_reservation_id), '') = '' then
    raise exception 'invalid_batch_reservation_identity';
  end if;
  if p_actual_nanos is null or p_actual_nanos < 0 then
    raise exception 'invalid_actual_nanos';
  end if;

  select * into v_reservation
  from public.gateway_wallet_reservations
  where workspace_id = p_workspace_id and reservation_id = p_reservation_id
  for update;
  if not found then
    return query select false, false, 'reservation_not_found'::text, p_actual_nanos,
      null::bigint, null::bigint, null::bigint, null::bigint;
    return;
  end if;

  select * into v_wallet from public.wallets
  where workspace_id = p_workspace_id for update;
  if not found then
    return query select false, false, 'wallet_not_found'::text, p_actual_nanos,
      null::bigint, null::bigint, null::bigint, null::bigint;
    return;
  end if;

  if v_reservation.status = 'captured' then
    if coalesce(v_reservation.settled_amount_nanos, v_reservation.amount_nanos) <> p_actual_nanos then
      raise exception 'reservation_settlement_amount_mismatch';
    end if;
    return query select true, false, 'already_captured'::text, p_actual_nanos,
      coalesce(v_wallet.balance_nanos, 0), coalesce(v_wallet.balance_nanos, 0),
      coalesce(v_wallet.reserved_nanos, 0), coalesce(v_wallet.reserved_nanos, 0);
    return;
  end if;

  if v_reservation.status not in ('held', 'reserved') then
    return query select false, false, 'reservation_not_active'::text, p_actual_nanos,
      coalesce(v_wallet.balance_nanos, 0), coalesce(v_wallet.balance_nanos, 0),
      coalesce(v_wallet.reserved_nanos, 0), coalesce(v_wallet.reserved_nanos, 0);
    return;
  end if;
  if coalesce(v_wallet.reserved_nanos, 0) < v_reservation.amount_nanos then
    return query select false, false, 'reserved_balance_mismatch'::text, p_actual_nanos,
      coalesce(v_wallet.balance_nanos, 0), coalesce(v_wallet.balance_nanos, 0),
      coalesce(v_wallet.reserved_nanos, 0), coalesce(v_wallet.reserved_nanos, 0);
    return;
  end if;

  -- The reservation itself is available to this settlement; all other holds
  -- remain excluded from spendable balance.
  v_available_for_settlement := coalesce(v_wallet.balance_nanos, 0)
    - coalesce(v_wallet.reserved_nanos, 0)
    + v_reservation.amount_nanos;
  if p_actual_nanos > v_available_for_settlement then
    return query select false, false, 'insufficient_balance'::text, p_actual_nanos,
      coalesce(v_wallet.balance_nanos, 0), coalesce(v_wallet.balance_nanos, 0),
      coalesce(v_wallet.reserved_nanos, 0), coalesce(v_wallet.reserved_nanos, 0);
    return;
  end if;

  v_before_balance := coalesce(v_wallet.balance_nanos, 0);
  v_before_reserved := coalesce(v_wallet.reserved_nanos, 0);
  update public.wallets
  set balance_nanos = v_before_balance - p_actual_nanos,
      reserved_nanos = v_before_reserved - v_reservation.amount_nanos,
      updated_at = now()
  where workspace_id = p_workspace_id
  returning * into v_wallet;

  update public.gateway_wallet_reservations
  set status = 'captured',
      settled_amount_nanos = p_actual_nanos,
      capture_ref_id = nullif(trim(coalesce(p_settle_ref_id, '')), ''),
      captured_at = now(),
      updated_at = now()
  where workspace_id = p_workspace_id and reservation_id = p_reservation_id;

  return query select true, true, null::text, p_actual_nanos,
    v_before_balance, coalesce(v_wallet.balance_nanos, 0),
    v_before_reserved, coalesce(v_wallet.reserved_nanos, 0);
end;

