declare
  v_app_count integer;
  v_gateway_requests integer := 0;
  v_request_facts integer := 0;
  v_since timestamptz;
  v_until timestamptz;
begin
  if p_workspace_id is null or p_source_app_id is null or p_target_app_id is null
     or p_source_app_id = p_target_app_id then
    raise exception using errcode = '22023', message = 'invalid_app_merge';
  end if;

  select count(*)::integer into v_app_count
  from public.api_apps app
  where app.workspace_id = p_workspace_id
    and app.id in (p_source_app_id, p_target_app_id);
  if v_app_count <> 2 then
    raise exception using errcode = '23503', message = 'app_merge_target_not_found';
  end if;

  select min(fact.occurred_at), max(fact.occurred_at)
  into v_since, v_until
  from public.v2_request_facts fact
  where fact.workspace_id = p_workspace_id
    and fact.app_id = p_source_app_id;

  update public.gateway_requests request
  set app_id = p_target_app_id
  where request.workspace_id = p_workspace_id
    and request.app_id = p_source_app_id;
  get diagnostics v_gateway_requests = row_count;

  update public.v2_request_facts fact
  set app_id = p_target_app_id
  where fact.workspace_id = p_workspace_id
    and fact.app_id = p_source_app_id;
  get diagnostics v_request_facts = row_count;

  -- Remove the source grains before deleting the app. Otherwise their foreign
  -- keys become null and retain stale traffic under an unattributed bucket.
  delete from public.v2_private_usage_daily rollup
  where rollup.workspace_id = p_workspace_id
    and rollup.app_id = p_source_app_id;
  delete from public.v2_public_usage_daily rollup
  where rollup.app_id = p_source_app_id;
  delete from public.v2_public_usage_hourly rollup
  where rollup.app_id = p_source_app_id;

  if v_since is not null then
    perform public.refresh_v2_analytics_range(
      v_since,
      v_until + interval '1 microsecond',
      p_workspace_id
    );
  end if;

  delete from public.api_apps app
  where app.workspace_id = p_workspace_id
    and app.id = p_source_app_id;

  return jsonb_build_object(
    'gateway_requests', v_gateway_requests,
    'request_facts', v_request_facts
  );
end;

declare
  v_user_id uuid := auth.uid();
  v_current_month_start_ts timestamptz := (date_trunc('month', now() at time zone 'UTC') at time zone 'UTC');
  v_prev_month_start_ts timestamptz := ((date_trunc('month', now() at time zone 'UTC') - interval '1 month') at time zone 'UTC');
  v_prev_month_nanos bigint := 0;
  v_prev_month_cents bigint := 0;
begin
  if p_workspace_id is null then
    raise exception 'workspace_id_required';
  end if;

  if v_user_id is null then
    raise exception 'unauthorized';
  end if;

  if not exists (
    select 1
    from public.workspace_members wm
    where wm.workspace_id = p_workspace_id
      and wm.user_id = v_user_id
  ) and not exists (
    select 1
    from public.workspaces w
    where w.id = p_workspace_id
      and w.owner_user_id = v_user_id
  ) then
    raise exception 'workspace_forbidden';
  end if;

  select coalesce(sum(gr.cost_nanos), 0)::bigint
  into v_prev_month_nanos
  from private.v2_rpc_gateway_requests_compat gr
  where gr.workspace_id = p_workspace_id
    and gr.success is true
    and gr.created_at >= v_prev_month_start_ts
    and gr.created_at < v_current_month_start_ts;

  v_prev_month_cents := floor(v_prev_month_nanos::numeric / 10000000.0)::bigint;
  return v_prev_month_cents;
end;

declare
  month_start_utc timestamptz :=
    (date_trunc('month', (now() at time zone 'Europe/London'))
     at time zone 'Europe/London');
  total bigint;
begin
  select coalesce(sum(amount_nanos),0)::bigint into total
  from credit_ledger
  where team_id = p_team
    and created_at >= month_start_utc
    and created_at <  now()
    and kind in ('top_up','auto_top_up');
  return total;
end;

declare
  v_user_id uuid := auth.uid();
  v_now_utc timestamptz := now();
  v_current_month_start_ts timestamptz := (date_trunc('month', now() at time zone 'UTC') at time zone 'UTC');
  v_mtd_nanos bigint := 0;
  v_mtd_cents bigint := 0;
begin
  if p_workspace_id is null then
    raise exception 'workspace_id_required';
  end if;

  if v_user_id is null then
    raise exception 'unauthorized';
  end if;

  if not exists (
    select 1
    from public.workspace_members wm
    where wm.workspace_id = p_workspace_id
      and wm.user_id = v_user_id
  ) and not exists (
    select 1
    from public.workspaces w
    where w.id = p_workspace_id
      and w.owner_user_id = v_user_id
  ) then
    raise exception 'workspace_forbidden';
  end if;

  select coalesce(sum(gr.cost_nanos), 0)::bigint
  into v_mtd_nanos
  from private.v2_rpc_gateway_requests_compat gr
  where gr.workspace_id = p_workspace_id
    and gr.success is true
    and gr.created_at >= v_current_month_start_ts
    and gr.created_at <= v_now_utc;

  v_mtd_cents := floor(v_mtd_nanos::numeric / 10000000.0)::bigint;
  return v_mtd_cents;
end;

declare v_before jsonb; v_after jsonb; v_uuid uuid;
begin
  if not exists (select 1 from public.users where user_id = p_actor_user_id and lower(coalesce(role::text, '')) = 'admin') then raise exception 'actor must have the admin role'; end if;
  if p_action not in ('create','update','delete') then raise exception 'unsupported catalogue action'; end if;
  if p_resource_type = 'organisations' then
    select to_jsonb(t) into v_before from public.v2_labs t where lab_slug = p_resource_id;
    if p_action = 'delete' then delete from public.v2_labs where lab_slug = p_resource_id; else insert into public.v2_labs (lab_slug,name,country_code,description,status,metadata,updated_at) values (p_resource_id,p_payload->>'name',coalesce(nullif(p_payload->>'country_code',''),'xx'),nullif(p_payload->>'description',''),'active',jsonb_strip_nulls(jsonb_build_object('colour',p_payload->>'colour','source','admin')),now()) on conflict (lab_slug) do update set name=excluded.name,country_code=excluded.country_code,description=excluded.description,metadata=public.v2_labs.metadata||excluded.metadata,updated_at=now(); delete from public.v2_lab_links where lab_slug=p_resource_id; insert into public.v2_lab_links(lab_slug,platform,url) select p_resource_id,x->>'platform',x->>'url' from jsonb_array_elements(coalesce(p_payload->'social_links','[]'::jsonb)) x; end if;
    select to_jsonb(t) into v_after from public.v2_labs t where lab_slug = p_resource_id;
  elsif p_resource_type = 'providers' then
    select to_jsonb(t) into v_before from public.v2_providers t where provider_slug=p_resource_id;
    if p_action='delete' then delete from public.v2_providers where provider_slug=p_resource_id; else insert into public.v2_providers(provider_slug,name,status,country_code,base_url,metadata,updated_at) values(p_resource_id,p_payload->>'api_provider_name',lower(coalesce(nullif(p_payload->>'status',''),'active')),coalesce(nullif(p_payload->>'country_code',''),'xx'),nullif(p_payload->>'link',''),jsonb_strip_nulls(jsonb_build_object('description',p_payload->>'description','prompt_training_policy',p_payload->>'prompt_training_policy','prompt_training_notes',p_payload->>'prompt_training_notes','prompt_training_source_url',p_payload->>'prompt_training_source_url','data_policy_tier',p_payload->>'data_policy_tier','data_policy_confidence',p_payload->>'data_policy_confidence','data_policy_contract_mode',p_payload->>'data_policy_contract_mode','data_policy_contract_notes',p_payload->>'data_policy_contract_notes','source','admin')),now()) on conflict(provider_slug) do update set name=excluded.name,status=excluded.status,country_code=excluded.country_code,base_url=excluded.base_url,metadata=public.v2_providers.metadata||excluded.metadata,updated_at=now(); end if;
    select to_jsonb(t) into v_after from public.v2_providers t where provider_slug=p_resource_id;
  elsif p_resource_type = 'benchmarks' then
    select to_jsonb(t) into v_before from public.v2_benchmarks t where benchmark_id=p_resource_id;
    if p_action='delete' then delete from public.v2_benchmarks where benchmark_id=p_resource_id; else insert into public.v2_benchmarks(benchmark_id,name,category,link,ascending_order,updated_at) values(p_resource_id,p_payload->>'name',nullif(p_payload->>'category',''),nullif(p_payload->>'link',''),coalesce((p_payload->>'ascending_order')::boolean,false),now()) on conflict(benchmark_id) do update set name=excluded.name,category=excluded.category,link=excluded.link,ascending_order=excluded.ascending_order,updated_at=now(); end if;
    select to_jsonb(t) into v_after from public.v2_benchmarks t where benchmark_id=p_resource_id;
  elsif p_resource_type = 'subscription-plans' then
    v_uuid := p_resource_id::uuid; select to_jsonb(t) into v_before from public.v2_subscription_plans t where plan_uuid=v_uuid;
    if p_action='delete' then delete from public.v2_subscription_plans where plan_uuid=v_uuid; else insert into public.v2_subscription_plans(plan_uuid,plan_id,name,lab_slug,description,frequency,price,currency,link,other_info,updated_at) values(v_uuid,p_payload->>'plan_id',p_payload->>'name',nullif(p_payload->>'organisation_id',''),nullif(p_payload->>'description',''),nullif(p_payload->>'frequency',''),nullif(p_payload->>'price','')::numeric,nullif(p_payload->>'currency',''),nullif(p_payload->>'link',''),coalesce(p_payload->'other_info','{}'::jsonb)||jsonb_build_object('source','admin'),now()) on conflict(plan_uuid) do update set plan_id=excluded.plan_id,name=excluded.name,lab_slug=excluded.lab_slug,description=excluded.description,frequency=excluded.frequency,price=excluded.price,currency=excluded.currency,link=excluded.link,other_info=public.v2_subscription_plans.other_info||excluded.other_info,updated_at=now(); end if;
    select to_jsonb(t) into v_after from public.v2_subscription_plans t where plan_uuid=v_uuid;
  elsif p_resource_type = 'models' then
    select to_jsonb(t) into v_before from public.v2_models t where model_slug=p_resource_id;
    if p_action='delete' then delete from public.v2_models where model_slug=p_resource_id; else insert into public.v2_models(model_slug,lab_slug,name,status,hidden,input_modalities,output_modalities,family_slug,announced_at,released_at,deprecated_at,retired_at,metadata,updated_at) values(p_resource_id,p_payload->>'organisationId',p_payload->>'name',lower(coalesce(nullif(p_payload->>'status',''),'active')),coalesce((p_payload->>'hidden')::boolean,false),string_to_array(coalesce(p_payload->>'inputTypes',''),','),string_to_array(coalesce(p_payload->>'outputTypes',''),','),nullif(p_payload->>'familyId',''),nullif(p_payload->>'announcementDate','')::timestamptz,nullif(p_payload->>'releaseDate','')::timestamptz,nullif(p_payload->>'deprecationDate','')::timestamptz,nullif(p_payload->>'retirementDate','')::timestamptz,jsonb_strip_nulls(jsonb_build_object('license',p_payload->>'license','previous_model_id',p_payload->>'previousModelId','source','admin')),now()) on conflict(model_slug) do update set lab_slug=coalesce(excluded.lab_slug,public.v2_models.lab_slug),name=excluded.name,status=excluded.status,hidden=excluded.hidden,input_modalities=excluded.input_modalities,output_modalities=excluded.output_modalities,family_slug=excluded.family_slug,announced_at=excluded.announced_at,released_at=excluded.released_at,deprecated_at=excluded.deprecated_at,retired_at=excluded.retired_at,metadata=public.v2_models.metadata||excluded.metadata,updated_at=now(); end if;
    select to_jsonb(t) into v_after from public.v2_models t where model_slug=p_resource_id;
  else raise exception 'unsupported catalogue resource'; end if;
  insert into public.v2_catalogue_admin_changes(actor_user_id,resource_type,resource_id,action,before_state,after_state) values(p_actor_user_id,p_resource_type,p_resource_id,p_action,v_before,v_after);
  insert into public.v2_catalogue_source_overrides(source_type,source_key,disposition,actor_user_id,resource_id,updated_at) values(p_resource_type,p_resource_id,case when p_action='delete' then 'suppressed' else 'database_managed' end,p_actor_user_id,p_resource_id,now()) on conflict(source_type,source_key) do update set disposition=excluded.disposition,actor_user_id=excluded.actor_user_id,resource_id=excluded.resource_id,updated_at=now();
  return jsonb_build_object('before',v_before,'after',v_after);
end

declare v_before jsonb; v_after jsonb;
begin
  if not exists(select 1 from public.users where user_id=p_actor_user_id and lower(coalesce(role::text,''))='admin') then raise exception 'actor must have the admin role'; end if;
  select to_jsonb(t) into v_before from public.v2_models t where model_slug=p_model_slug for update;
  if v_before is null then raise exception 'model not found'; end if;

  update public.v2_models set
    name=coalesce(p_payload->>'name',name), lab_slug=coalesce(p_payload->>'organisation_id',lab_slug),
    status=coalesce(lower(p_payload->>'status'),status), hidden=coalesce((p_payload->>'hidden')::boolean,hidden),
    family_slug=case when p_payload ? 'family_id' then nullif(p_payload->>'family_id','') else family_slug end,
    input_modalities=case when p_payload ? 'input_types' then string_to_array(coalesce(p_payload->>'input_types',''),',') else input_modalities end,
    output_modalities=case when p_payload ? 'output_types' then string_to_array(coalesce(p_payload->>'output_types',''),',') else output_modalities end,
    announced_at=case when p_payload ? 'announcement_date' then nullif(p_payload->>'announcement_date','')::timestamptz else announced_at end,
    released_at=case when p_payload ? 'release_date' then nullif(p_payload->>'release_date','')::timestamptz else released_at end,
    deprecated_at=case when p_payload ? 'deprecation_date' then nullif(p_payload->>'deprecation_date','')::timestamptz else deprecated_at end,
    retired_at=case when p_payload ? 'retirement_date' then nullif(p_payload->>'retirement_date','')::timestamptz else retired_at end,
    metadata=metadata||jsonb_strip_nulls(jsonb_build_object('license',p_payload->>'license','previous_model_id',p_payload->>'previous_model_id','source','admin')),updated_at=now()
  where model_slug=p_model_slug;

  if p_payload ? 'family' then
    insert into public.v2_model_families(family_slug,lab_slug,name,metadata,updated_at)
    values(p_payload->'family'->>'family_id',(select lab_slug from public.v2_models where model_slug=p_model_slug),p_payload->'family'->>'family_name',jsonb_strip_nulls(jsonb_build_object('description',p_payload->'family'->>'family_description','source','admin')),now())
    on conflict(family_slug) do update set name=excluded.name,metadata=public.v2_model_families.metadata||excluded.metadata,updated_at=now();
    update public.v2_models set family_slug=p_payload->'family'->>'family_id',updated_at=now() where model_slug=p_model_slug;
  end if;

  if p_payload ? 'model_details' then
    delete from public.v2_model_details where model_slug=p_model_slug;
    insert into public.v2_model_details(model_slug,detail_name,detail_value,detail_order)
    select p_model_slug,x->>'detail_name',coalesce(x->'detail_value',to_jsonb(x->>'detail_value')),100+row_number() over()
    from jsonb_array_elements(p_payload->'model_details') x;
  end if;
  if p_payload ? 'links' then
    delete from public.v2_model_links where model_slug=p_model_slug;
    insert into public.v2_model_links(model_slug,link_kind,title,url,metadata)
    select p_model_slug,coalesce(nullif(x->>'kind',''),x->>'platform'),coalesce(nullif(x->>'title',''),x->>'platform'),x->>'url',jsonb_build_object('source','admin') from jsonb_array_elements(p_payload->'links') x;
  end if;
  if p_payload ? 'benchmark_results' then
    delete from public.v2_benchmark_results where model_slug=p_model_slug;
    insert into public.v2_benchmark_results(model_slug,benchmark_id,score,score_numeric,is_self_reported,other_info,source_link,variant,updated_at)
    select p_model_slug,x->>'benchmark_id',x->>'score',case when (x->>'score')~'^[-+]?[0-9]*\.?[0-9]+$' then (x->>'score')::numeric end,coalesce((x->>'is_self_reported')::boolean,false),nullif(x->>'other_info',''),nullif(x->>'source_link',''),nullif(x->>'variant',''),now() from jsonb_array_elements(p_payload->'benchmark_results') x;
  end if;
  if p_payload ? 'subscription_plan_models' then
    delete from public.v2_subscription_plan_models where model_slug=p_model_slug;
    insert into public.v2_subscription_plan_models(plan_uuid,model_slug,model_info,rate_limit,other_info)
    select (x->>'plan_uuid')::uuid,p_model_slug,coalesce(x->'model_info','{}'::jsonb),coalesce(x->'rate_limit','{}'::jsonb),coalesce(x->'other_info','{}'::jsonb) from jsonb_array_elements(p_payload->'subscription_plan_models') x;
  end if;
  if p_payload ? 'provider_models' then
    insert into public.v2_model_provider_routes(provider_model_id,model_slug,provider_slug,provider_model_slug,status,routing_enabled,input_modalities,output_modalities,context_length,max_output_tokens,effective_from,effective_to,metadata,updated_at)
    select
      case when coalesce(x->>'id','') like 'new-%' or coalesce(x->>'id','')='' then (x->>'provider_id')||':'||p_model_slug||':'||coalesce(nullif(x->>'provider_model_slug',''),x->>'api_model_id') else x->>'id' end,
      p_model_slug,x->>'provider_id',coalesce(nullif(x->>'provider_model_slug',''),x->>'api_model_id'),'active',coalesce((x->>'is_active_gateway')::boolean,false),
      case when jsonb_typeof(x->'input_modalities')='array' then array(select jsonb_array_elements_text(x->'input_modalities')) else string_to_array(coalesce(x->>'input_modalities',''),',') end,
      case when jsonb_typeof(x->'output_modalities')='array' then array(select jsonb_array_elements_text(x->'output_modalities')) else string_to_array(coalesce(x->>'output_modalities',''),',') end,
      nullif(x->>'context_length','')::integer,nullif(x->>'max_output_tokens','')::integer,nullif(x->>'effective_from','')::timestamptz,nullif(x->>'effective_to','')::timestamptz,
      jsonb_strip_nulls(jsonb_build_object('prompt_training_policy_override',x->>'prompt_training_policy_override','prompt_training_override_notes',x->>'prompt_training_override_notes','prompt_training_override_source_url',x->>'prompt_training_override_source_url','quantization_scheme',x->>'quantization_scheme','source','admin')),now()
    from jsonb_array_elements(p_payload->'provider_models') x
    on conflict(provider_model_id) do update set provider_slug=excluded.provider_slug,provider_model_slug=excluded.provider_model_slug,status=excluded.status,routing_enabled=excluded.routing_enabled,input_modalities=excluded.input_modalities,output_modalities=excluded.output_modalities,context_length=excluded.context_length,max_output_tokens=excluded.max_output_tokens,effective_from=excluded.effective_from,effective_to=excluded.effective_to,metadata=public.v2_model_provider_routes.metadata||excluded.metadata,updated_at=now();
    delete from public.v2_model_provider_routes route where route.model_slug=p_model_slug and not exists (
      select 1 from jsonb_array_elements(p_payload->'provider_models') x where route.provider_model_id=case when coalesce(x->>'id','') like 'new-%' or coalesce(x->>'id','')='' then (x->>'provider_id')||':'||p_model_slug||':'||coalesce(nullif(x->>'provider_model_slug',''),x->>'api_model_id') else x->>'id' end
    );
  end if;
  if p_payload ? 'provider_capabilities' then
    delete from public.v2_route_capabilities capability using public.v2_model_provider_routes route where capability.provider_model_id=route.provider_model_id and route.model_slug=p_model_slug;
    insert into public.v2_route_capabilities(provider_model_id,capability_id,status,params,effective_from,effective_to,metadata,updated_at)
    select route.provider_model_id,x->>'capability_id',case when x->>'status' like 'deranked_%' then 'degraded' else coalesce(nullif(x->>'status',''),'active') end,coalesce(x->'params','{}'::jsonb),nullif(x->>'effective_from','')::timestamptz,nullif(x->>'effective_to','')::timestamptz,jsonb_build_object('editor_status',x->>'status','source','admin'),now()
    from jsonb_array_elements(p_payload->'provider_capabilities') x join public.v2_model_provider_routes route on route.model_slug=p_model_slug and route.provider_slug=x->>'provider_id' and route.provider_model_slug=coalesce(nullif(x->>'provider_model_slug',''),x->>'api_model_id');
  end if;
  select to_jsonb(t) into v_after from public.v2_models t where model_slug=p_model_slug;
  insert into public.v2_catalogue_admin_changes(actor_user_id,resource_type,resource_id,action,before_state,after_state)
  values(p_actor_user_id,'model_graph',p_model_slug,'save',v_before,v_after);
  insert into public.v2_catalogue_source_overrides(source_type,source_key,disposition,actor_user_id,resource_id,updated_at)
  values('model',p_model_slug,'database',p_actor_user_id,p_model_slug,now()) on conflict(source_type,source_key) do update set disposition='database',actor_user_id=excluded.actor_user_id,updated_at=now();
  return jsonb_build_object('model',v_after);
end

declare
  v_sku_id uuid;
  v_provider_model_id text;
  v_existing public.v2_pricing_skus%rowtype;
  v_before jsonb;
  v_after jsonb;
  v_meter jsonb;
  v_resource_id text;
begin
  if p_actor_user_id is null then
    raise exception 'actor_user_id is required';
  end if;
  if coalesce(trim(p_model_slug), '') = '' then
    raise exception 'model_slug is required';
  end if;
  if p_action not in ('save', 'delete') then
    raise exception 'unsupported pricing mutation action';
  end if;
  if not exists (
    select 1 from public.users
    where user_id = p_actor_user_id
      and lower(coalesce(role::text, '')) = 'admin'
  ) then
    raise exception 'actor must have the admin role';
  end if;

  if nullif(p_sku->>'sku_id', '') is not null then
    begin
      v_sku_id := (p_sku->>'sku_id')::uuid;
    exception when invalid_text_representation then
      raise exception 'sku_id must be a UUID';
    end;
  end if;

  if v_sku_id is not null then
    select * into v_existing
    from public.v2_pricing_skus
    where sku_id = v_sku_id;

    if found then
      select jsonb_build_object(
        'sku', to_jsonb(v_existing),
        'meters', coalesce((
          select jsonb_agg(to_jsonb(meter) order by meter.meter_order, meter.meter_key)
          from public.v2_pricing_sku_meters meter
          where meter.sku_id = v_sku_id
        ), '[]'::jsonb)
      ) into v_before;

      if not exists (
        select 1
        from public.v2_model_provider_routes route
        where route.provider_model_id = v_existing.provider_model_id
          and route.model_slug = p_model_slug
      ) then
        raise exception 'pricing SKU does not belong to the requested model';
      end if;
    end if;
  end if;

  if p_action = 'delete' then
    if v_sku_id is null or v_before is null then
      raise exception 'pricing SKU not found';
    end if;
    delete from public.v2_pricing_skus where sku_id = v_sku_id;
    v_resource_id := v_sku_id::text;
    insert into public.v2_catalogue_admin_changes (
      actor_user_id, resource_type, resource_id, action, before_state, after_state
    ) values (
      p_actor_user_id, 'pricing_sku', v_resource_id, 'delete', v_before, null
    );
    if nullif(v_existing.metadata->>'source_key', '') is not null then
      insert into public.v2_catalogue_source_overrides (
        source_type, source_key, disposition, actor_user_id, resource_id, updated_at
      ) values (
        'pricing_rule', v_existing.metadata->>'source_key', 'suppressed', p_actor_user_id, v_resource_id, now()
      )
      on conflict (source_type, source_key) do update set
        disposition = excluded.disposition,
        actor_user_id = excluded.actor_user_id,
        resource_id = excluded.resource_id,
        updated_at = now();
    end if;
    return jsonb_build_object('deleted', true, 'sku_id', v_resource_id);
  end if;

  v_provider_model_id := nullif(trim(p_sku->>'provider_model_id'), '');
  if v_provider_model_id is null then
    raise exception 'provider_model_id is required';
  end if;
  if not exists (
    select 1
    from public.v2_model_provider_routes route
    where route.provider_model_id = v_provider_model_id
      and route.model_slug = p_model_slug
  ) then
    raise exception 'provider route does not belong to the requested model';
  end if;
  if jsonb_typeof(coalesce(p_sku->'meters', '[]'::jsonb)) <> 'array'
     or jsonb_array_length(coalesce(p_sku->'meters', '[]'::jsonb)) = 0 then
    raise exception 'at least one pricing meter is required';
  end if;

  v_sku_id := coalesce(v_sku_id, gen_random_uuid());
  insert into public.v2_pricing_skus (
    sku_id,
    provider_model_id,
    sku_code,
    version,
    operation,
    status,
    region,
    service_tier_slug,
    display_name,
    description,
    currency,
    effective_from,
    effective_to,
    metadata,
    updated_at
  ) values (
    v_sku_id,
    v_provider_model_id,
    lower(trim(p_sku->>'sku_code')),
    coalesce((p_sku->>'version')::integer, 1),
    coalesce(nullif(trim(p_sku->>'operation'), ''), 'inference'),
    coalesce(nullif(trim(p_sku->>'status'), ''), 'active'),
    nullif(trim(p_sku->>'region'), ''),
    coalesce(nullif(trim(p_sku->>'service_tier_slug'), ''), 'standard'),
    trim(p_sku->>'display_name'),
    nullif(trim(p_sku->>'description'), ''),
    upper(coalesce(nullif(trim(p_sku->>'currency'), ''), 'USD')),
    coalesce((p_sku->>'effective_from')::timestamptz, now()),
    nullif(p_sku->>'effective_to', '')::timestamptz,
    coalesce(p_sku->'metadata', '{}'::jsonb) || jsonb_build_object(
      'source', 'admin',
      'authored_by', p_actor_user_id,
      'authored_at', now()
    ),
    now()
  )
  on conflict (sku_id) do update set
    provider_model_id = excluded.provider_model_id,
    sku_code = excluded.sku_code,
    version = excluded.version,
    operation = excluded.operation,
    status = excluded.status,
    region = excluded.region,
    service_tier_slug = excluded.service_tier_slug,
    display_name = excluded.display_name,
    description = excluded.description,
    currency = excluded.currency,
    effective_from = excluded.effective_from,
    effective_to = excluded.effective_to,
    metadata = excluded.metadata,
    updated_at = now();

  delete from public.v2_pricing_sku_meters where sku_id = v_sku_id;

  for v_meter in select value from jsonb_array_elements(p_sku->'meters')
  loop
    insert into public.v2_pricing_sku_meters (
      sku_id,
      meter_key,
      modality,
      direction,
      unit,
      unit_quantity,
      price_nanos,
      display_label,
      display_unit,
      billable,
      meter_order,
      metadata
    ) values (
      v_sku_id,
      lower(trim(v_meter->>'meter_key')),
      lower(trim(v_meter->>'modality')),
      nullif(lower(trim(v_meter->>'direction')), ''),
      lower(trim(v_meter->>'unit')),
      (v_meter->>'unit_quantity')::numeric,
      (v_meter->>'price_nanos')::numeric,
      trim(v_meter->>'display_label'),
      trim(v_meter->>'display_unit'),
      coalesce((v_meter->>'billable')::boolean, true),
      coalesce((v_meter->>'meter_order')::integer, 100),
      coalesce(v_meter->'metadata', '{}'::jsonb) || jsonb_build_object('source', 'admin')
    );
  end loop;

  select jsonb_build_object(
    'sku', to_jsonb(sku),
    'meters', coalesce((
      select jsonb_agg(to_jsonb(meter) order by meter.meter_order, meter.meter_key)
      from public.v2_pricing_sku_meters meter
      where meter.sku_id = v_sku_id
    ), '[]'::jsonb)
  ) into v_after
  from public.v2_pricing_skus sku
  where sku.sku_id = v_sku_id;

  v_resource_id := v_sku_id::text;
  insert into public.v2_catalogue_admin_changes (
    actor_user_id, resource_type, resource_id, action, before_state, after_state
  ) values (
    p_actor_user_id,
    'pricing_sku',
    v_resource_id,
    case when v_before is null then 'create' else 'update' end,
    v_before,
    v_after
  );

  if nullif(p_sku->'metadata'->>'source_key', '') is not null then
    insert into public.v2_catalogue_source_overrides (
      source_type, source_key, disposition, actor_user_id, resource_id, updated_at
    ) values (
      'pricing_rule', p_sku->'metadata'->>'source_key', 'database_managed', p_actor_user_id, v_resource_id, now()
    )
    on conflict (source_type, source_key) do update set
      disposition = excluded.disposition,
      actor_user_id = excluded.actor_user_id,
      resource_id = excluded.resource_id,
      updated_at = now();
  end if;

  return v_after;
end;

declare
  v_provider_slug text := nullif(trim(p_route->>'provider_slug'),'');
  v_provider_model_slug text := nullif(trim(p_route->>'provider_model_slug'),'');
  v_provider_model_id text := nullif(trim(p_route->>'provider_model_id'),'');
  v_before jsonb;
  v_after jsonb;
begin
  if not exists(select 1 from public.users where user_id=p_actor_user_id and lower(coalesce(role::text,''))='admin') then raise exception 'actor must have the admin role'; end if;
  if not exists(select 1 from public.v2_models where model_slug=p_model_slug) then raise exception 'model not found'; end if;
  if v_provider_slug is null or not exists(select 1 from public.v2_providers where provider_slug=v_provider_slug) then raise exception 'provider not found'; end if;
  if v_provider_model_slug is null then raise exception 'provider_model_slug is required'; end if;
  if v_provider_model_id is null then v_provider_model_id := v_provider_slug||':'||p_model_slug||':'||v_provider_model_slug; end if;
  select to_jsonb(t) into v_before from public.v2_model_provider_routes t where provider_model_id=v_provider_model_id;
  insert into public.v2_model_provider_routes(
    provider_model_id,model_slug,provider_slug,provider_model_slug,status,routing_enabled,
    input_modalities,output_modalities,regions,context_length,max_output_tokens,
    effective_from,effective_to,metadata,updated_at
  ) values (
    v_provider_model_id,p_model_slug,v_provider_slug,v_provider_model_slug,
    coalesce(nullif(p_route->>'status',''),'active'),coalesce((p_route->>'routing_enabled')::boolean,false),
    case when jsonb_typeof(p_route->'input_modalities')='array' then array(select jsonb_array_elements_text(p_route->'input_modalities')) else '{}'::text[] end,
    case when jsonb_typeof(p_route->'output_modalities')='array' then array(select jsonb_array_elements_text(p_route->'output_modalities')) else '{}'::text[] end,
    case when jsonb_typeof(p_route->'regions')='array' then array(select jsonb_array_elements_text(p_route->'regions')) else '{}'::text[] end,
    nullif(p_route->>'context_length','')::integer,nullif(p_route->>'max_output_tokens','')::integer,
    nullif(p_route->>'effective_from','')::timestamptz,nullif(p_route->>'effective_to','')::timestamptz,
    jsonb_build_object('source','admin'),now()
  ) on conflict(provider_model_id) do update set
    provider_slug=excluded.provider_slug,provider_model_slug=excluded.provider_model_slug,status=excluded.status,
    routing_enabled=excluded.routing_enabled,input_modalities=excluded.input_modalities,output_modalities=excluded.output_modalities,
    regions=excluded.regions,context_length=excluded.context_length,max_output_tokens=excluded.max_output_tokens,
    effective_from=excluded.effective_from,effective_to=excluded.effective_to,
    metadata=public.v2_model_provider_routes.metadata||excluded.metadata,updated_at=now();
  select to_jsonb(t) into v_after from public.v2_model_provider_routes t where provider_model_id=v_provider_model_id;
  insert into public.v2_catalogue_admin_changes(actor_user_id,resource_type,resource_id,action,before_state,after_state)
  values(p_actor_user_id,'provider_route',v_provider_model_id,case when v_before is null then 'create' else 'update' end,v_before,v_after);
  insert into public.v2_catalogue_source_overrides(source_type,source_key,disposition,actor_user_id,resource_id,updated_at)
  values('provider_route',v_provider_model_id,'database_managed',p_actor_user_id,v_provider_model_id,now())
  on conflict(source_type,source_key) do update set disposition='database_managed',actor_user_id=excluded.actor_user_id,resource_id=excluded.resource_id,updated_at=now();
  return v_after;
end

begin
  new.usage_embedding_tokens :=
    case
      when coalesce(new.endpoint, '') = 'embeddings' then
        public.gateway_usage_nonnegative_bigint(
          coalesce(
            public.gateway_usage_numeric_field(
              new.usage,
              'embedding_tokens',
              'input_tokens',
              'prompt_tokens',
              'total_tokens'
            ),
            new.usage_embedding_tokens,
            0
          )
        )
      else greatest(coalesce(new.usage_embedding_tokens, 0), 0)
    end;
  return new;
end;

declare
  v_usage jsonb := coalesce(new.usage, '{}'::jsonb);
  v_input_tokens bigint;
  v_output_tokens bigint;
  v_total_tokens bigint;
  v_reasoning_tokens bigint;
  v_input_image_tokens bigint;
  v_output_image_tokens bigint;
  v_input_audio_tokens bigint;
  v_output_audio_tokens bigint;
  v_input_video_tokens bigint;
  v_output_video_tokens bigint;
begin
  v_total_tokens := public.gateway_usage_total_tokens(v_usage);

  v_input_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'input_tokens',
      'prompt_tokens',
      'inputTokens',
      'promptTokens',
      'promptTokenCount',
      'total_input_tokens',
      'totalInputTokens'
    ), 0)
  );
  v_output_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'output_tokens',
      'completion_tokens',
      'outputTokens',
      'completionTokens',
      'candidatesTokenCount',
      'total_output_tokens',
      'totalOutputTokens'
    ), 0)
  );
  v_reasoning_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'reasoning_tokens',
      'reasoning_output_tokens',
      'output_reasoning_tokens',
      'completion_tokens_details.reasoning_tokens',
      'output_tokens_details.reasoning_tokens'
    ), 0)
  );
  v_input_image_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'input_image_tokens',
      'image_input_tokens',
      'prompt_image_tokens',
      'input_tokens_details.image_tokens',
      'prompt_tokens_details.image_tokens'
    ), 0)
  );
  v_output_image_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'output_image_tokens',
      'image_output_tokens',
      'generated_image_tokens',
      'completion_tokens_details.image_tokens',
      'output_tokens_details.image_tokens'
    ), 0)
  );
  v_input_audio_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'input_audio_tokens',
      'audio_input_tokens',
      'prompt_audio_tokens',
      'input_tokens_details.audio_tokens',
      'prompt_tokens_details.audio_tokens'
    ), 0)
  );
  v_output_audio_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'output_audio_tokens',
      'audio_output_tokens',
      'completion_tokens_details.audio_tokens',
      'output_tokens_details.audio_tokens'
    ), 0)
  );
  v_input_video_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'input_video_tokens',
      'video_input_tokens',
      'input_tokens_details.video_tokens',
      'prompt_tokens_details.video_tokens'
    ), 0)
  );
  v_output_video_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'output_video_tokens',
      'video_output_tokens',
      'completion_tokens_details.video_tokens',
      'output_tokens_details.video_tokens'
    ), 0)
  );

  if v_total_tokens < v_input_tokens + v_output_tokens + v_reasoning_tokens then
    v_total_tokens := v_input_tokens + v_output_tokens + v_reasoning_tokens;
  end if;

  new.usage_total_tokens := coalesce(v_total_tokens, 0);
  new.usage_input_tokens := v_input_tokens;
  new.usage_output_tokens := v_output_tokens;
  new.usage_reasoning_tokens := v_reasoning_tokens;
  new.usage_input_image_tokens := v_input_image_tokens;
  new.usage_output_image_tokens := v_output_image_tokens;
  new.usage_input_audio_tokens := v_input_audio_tokens;
  new.usage_output_audio_tokens := v_output_audio_tokens;
  new.usage_input_video_tokens := v_input_video_tokens;
  new.usage_output_video_tokens := v_output_video_tokens;
  new.usage_input_text_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(
      public.gateway_usage_numeric_field(v_usage, 'input_text_tokens', 'text_input_tokens'),
      greatest(v_input_tokens - v_input_image_tokens - v_input_audio_tokens - v_input_video_tokens, 0)
    )
  );
  new.usage_output_text_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(
      public.gateway_usage_numeric_field(v_usage, 'output_text_tokens', 'text_output_tokens'),
      greatest(v_output_tokens - v_output_image_tokens - v_output_audio_tokens - v_output_video_tokens - v_reasoning_tokens, 0)
    )
  );

  new.usage_image_inputs := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'input_image_count',
      'image_input_count',
      'image_inputs',
      'input_images'
    ), 0)
  );
  new.usage_image_outputs := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'output_image_count',
      'image_output_count',
      'image_outputs',
      'output_images',
      'generated_images',
      'image_count'
    ), 0)
  );
  new.usage_audio_inputs := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'input_audio_count',
      'audio_input_count',
      'audio_inputs',
      'input_audio'
    ), 0)
  );
  new.usage_audio_outputs := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'output_audio_count',
      'audio_output_count',
      'audio_outputs',
      'output_audio'
    ), 0)
  );
  new.usage_video_inputs := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'input_video_count',
      'video_input_count',
      'video_inputs',
      'input_videos'
    ), 0)
  );
  new.usage_video_outputs := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'output_video_count',
      'video_output_count',
      'video_outputs',
      'output_videos',
      'video_count'
    ), 0)
  );

  new.usage_cached_read_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'cached_read_tokens',
      'cache_read_input_tokens',
      'input_tokens_details.cached_tokens',
      'prompt_tokens_details.cached_tokens'
    ), 0)
  );
  new.usage_cached_write_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'cached_write_tokens',
      'cache_creation_input_tokens',
      'output_tokens_details.cached_tokens'
    ), 0)
  );
  new.usage_cached_read_text_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_read_text_tokens'), 0)
  );
  new.usage_cached_write_text_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(
      public.gateway_usage_numeric_field(v_usage, 'cached_write_text_tokens'),
      coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_write_text_tokens_5m', 'cache_creation.ephemeral_5m_input_tokens'), 0) +
        coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_write_text_tokens_1h', 'cache_creation.ephemeral_1h_input_tokens'), 0)
    )
  );
  new.usage_cached_write_text_tokens_5m := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_write_text_tokens_5m', 'cache_creation.ephemeral_5m_input_tokens'), 0)
  );
  new.usage_cached_write_text_tokens_1h := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_write_text_tokens_1h', 'cache_creation.ephemeral_1h_input_tokens'), 0)
  );
  new.usage_cached_read_image_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_read_image_tokens'), 0)
  );
  new.usage_cached_write_image_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_write_image_tokens'), 0)
  );
  new.usage_cached_read_audio_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_read_audio_tokens'), 0)
  );
  new.usage_cached_write_audio_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_write_audio_tokens'), 0)
  );
  new.usage_cached_read_video_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_read_video_tokens'), 0)
  );
  new.usage_cached_write_video_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_write_video_tokens'), 0)
  );
  new.usage_input_quad_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'input_quad_tokens', 'quad_input_tokens'), new.usage_input_quad_tokens)
  );
  new.usage_output_quad_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'output_quad_tokens', 'quad_output_tokens'), new.usage_output_quad_tokens)
  );
  new.usage_total_quad_tokens := public.gateway_usage_nonnegative_bigint(
    greatest(
      coalesce(public.gateway_usage_numeric_field(v_usage, 'total_quad_tokens', 'quad_total_tokens'), new.usage_total_quad_tokens),
      new.usage_input_quad_tokens + new.usage_output_quad_tokens
    )
  );
  new.usage_text_quad_tokens := public.gateway_usage_nonnegative_bigint(
    greatest(
      coalesce(public.gateway_usage_numeric_field(v_usage, 'text_quad_tokens'), new.usage_text_quad_tokens),
      new.usage_total_quad_tokens
    )
  );
  new.usage_rerank_quad_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'rerank_quad_tokens'), new.usage_rerank_quad_tokens)
  );
  new.usage_embedding_quad_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'embedding_quad_tokens'), new.usage_embedding_quad_tokens)
  );
  new.usage_moderation_quad_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'moderation_quad_tokens'), new.usage_moderation_quad_tokens)
  );
  new.usage_ocr_quad_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'ocr_quad_tokens'), new.usage_ocr_quad_tokens)
  );
  new.usage_image_megapixels := greatest(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'image_megapixels'), new.usage_image_megapixels),
    0
  );
  new.usage_audio_seconds := greatest(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'audio_seconds'), new.usage_audio_seconds),
    0
  );
  new.usage_video_pixel_seconds := greatest(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'video_pixel_seconds'), new.usage_video_pixel_seconds),
    0
  );
  new.usage_input_characters := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'input_characters', 'input_chars'), new.usage_input_characters)
  );
  new.usage_output_characters := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'output_characters', 'output_chars'), new.usage_output_characters)
  );
  new.usage_total_characters := public.gateway_usage_nonnegative_bigint(
    greatest(
      coalesce(public.gateway_usage_numeric_field(v_usage, 'total_characters', 'total_chars'), new.usage_total_characters),
      new.usage_input_characters + new.usage_output_characters
    )
  );
  new.usage_normalized_at := now();

  return new;
end;

begin
  new.usage_video_seconds := greatest(
    coalesce(
      public.gateway_usage_numeric_field(
        new.usage,
        'video_seconds',
        'input_video_seconds',
        'output_video_seconds'
      ),
      new.usage_video_seconds,
      0
    ),
    0
  );
