declare source_row public.presets%rowtype;
begin
  if new.source_preset_id is null then
    new.root_preset_id := new.id;
    new.fork_depth := 0;
    return new;
  end if;
  select * into source_row from public.presets where id = new.source_preset_id;
  if not found then raise exception 'source_preset_not_found'; end if;
  new.root_preset_id := coalesce(source_row.root_preset_id, source_row.id);
  new.fork_depth := source_row.fork_depth + 1;
  new.source_preset_version_id := coalesce(new.source_preset_version_id, source_row.active_version_id);
  new.upstream_version_id := coalesce(new.upstream_version_id, source_row.active_version_id);
  return new;
end

begin
  if old.published_once_at is not null then
    if tg_op = 'UPDATE'
      and new.status = 'superseded'
      and new.superseded_at is not null
      and (to_jsonb(new) - 'status' - 'superseded_at') =
        (to_jsonb(old) - 'status' - 'superseded_at') then
      return new;
    end if;
    raise exception 'Published control-plane releases are immutable';
  end if;
  if tg_op = 'UPDATE' and new.status = 'published' then
    new.published_once_at := coalesce(new.published_once_at, new.published_at, now());
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;

declare
  old_release_published_at timestamptz;
  new_release_published_at timestamptz;
begin
  if tg_op in ('UPDATE', 'DELETE') then
    select published_once_at into old_release_published_at
      from public.v2_control_plane_releases where release_id = old.release_id;
    if old_release_published_at is not null then
      raise exception 'Execution plans in published releases are immutable';
    end if;
  end if;

  if tg_op in ('INSERT', 'UPDATE') then
    select published_once_at into new_release_published_at
      from public.v2_control_plane_releases where release_id = new.release_id;
    if new_release_published_at is not null then
      raise exception 'Execution plans in published releases are immutable';
    end if;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;

begin
  new.publisher_handle := lower(trim(new.publisher_handle));
  if exists (
    select 1 from public.workspace_publisher_handle_aliases alias
    where alias.handle = new.publisher_handle
      and alias.workspace_id <> new.id
  ) then
    raise exception 'publisher_handle_reserved' using errcode = '23505';
  end if;
  return new;
end

declare
  v_display_name text;
  v_default_workspace_id uuid;
  v_existing_workspace_id uuid;
  v_has_access boolean := false;
  v_default_workspace_is_owner boolean := false;
  v_created_workspace boolean := false;
  v_base_slug text;
  v_slug_attempt text;
  v_attempt integer := 0;
begin
  if p_user_id is null then
    raise exception using errcode = '22023', message = 'missing_user_id';
  end if;

  v_display_name := nullif(trim(coalesce(p_display_name, '')), '');
  if v_display_name is null then
    v_display_name := 'User';
  end if;

  insert into public.users (user_id, display_name)
  values (p_user_id, v_display_name)
  on conflict (user_id) do update
    set display_name = coalesce(nullif(excluded.display_name, ''), public.users.display_name);

  select u.default_workspace_id
  into v_default_workspace_id
  from public.users u
  where u.user_id = p_user_id
  limit 1;

  if v_default_workspace_id is not null then
    select exists (
      select 1
      from public.workspace_members wm
      where wm.workspace_id = v_default_workspace_id
        and wm.user_id = p_user_id

      union all

      select 1
      from public.workspaces w
      where w.id = v_default_workspace_id
        and w.owner_user_id = p_user_id
    )
    into v_has_access;

    select exists (
      select 1
      from public.workspaces w
      where w.id = v_default_workspace_id
        and w.owner_user_id = p_user_id
    )
    into v_default_workspace_is_owner;

    if v_has_access then
      if v_default_workspace_is_owner then
        insert into public.workspace_members (workspace_id, user_id, role)
        values (v_default_workspace_id, p_user_id, 'owner')
        on conflict on constraint workspace_members_pkey do nothing;
      end if;

      insert into public.workspace_settings (workspace_id)
      values (v_default_workspace_id)
      on conflict on constraint workspace_settings_pkey do nothing;

      return query
      select v_default_workspace_id, false;
      return;
    end if;

    update public.users
    set default_workspace_id = null
    where user_id = p_user_id
      and default_workspace_id = v_default_workspace_id;
  end if;

  select w.id
  into v_existing_workspace_id
  from public.workspaces w
  where w.owner_user_id = p_user_id
  order by w.created_at asc
  limit 1;

  if v_existing_workspace_id is null then
    v_base_slug := regexp_replace(lower(v_display_name), '[^a-z0-9]+', '-', 'g');
    v_base_slug := regexp_replace(v_base_slug, '^-+|-+$', '', 'g');
    if v_base_slug = '' then
      v_base_slug := 'user';
    end if;
    v_base_slug := left(v_base_slug, 42);
    v_slug_attempt := v_base_slug || '-personal';

    while v_attempt < 8 and v_existing_workspace_id is null loop
      begin
        insert into public.workspaces (name, slug, owner_user_id)
        values ('Personal', v_slug_attempt, p_user_id)
        returning id into v_existing_workspace_id;

        v_created_workspace := true;
      exception
        when unique_violation then
          v_attempt := v_attempt + 1;
          v_slug_attempt :=
            left(v_base_slug, 30) || '-personal-' || substring(md5(gen_random_uuid()::text), 1, 6);
      end;
    end loop;

    if v_existing_workspace_id is null then
      select w.id
      into v_existing_workspace_id
      from public.workspaces w
      where w.owner_user_id = p_user_id
      order by w.created_at asc
      limit 1;
    end if;
  end if;

  if v_existing_workspace_id is null then
    raise exception using errcode = 'P0001', message = 'personal_workspace_provision_failed';
  end if;

  insert into public.workspace_members (workspace_id, user_id, role)
  values (v_existing_workspace_id, p_user_id, 'owner')
  on conflict on constraint workspace_members_pkey do nothing;

  insert into public.workspace_settings (workspace_id)
  values (v_existing_workspace_id)
  on conflict on constraint workspace_settings_pkey do nothing;

  update public.users
  set default_workspace_id = v_existing_workspace_id
  where user_id = p_user_id;

  return query
  select v_existing_workspace_id, v_created_workspace;
end;

declare p public.presets%rowtype; next_number integer; next_label text; date_base text; date_count integer; published public.preset_versions%rowtype;
begin
  select * into p from public.presets where id = target_preset_id and archived_at is null for update;
  if not found then raise exception 'preset_not_found'; end if;
  if p.created_by <> actor_user_id and (
    coalesce(p.draft_visibility, p.visibility) = 'private' or not exists (
      select 1 from public.workspace_members member
      where member.workspace_id = p.workspace_id
        and member.user_id = actor_user_id
        and member.role in ('owner', 'admin')
    )
  ) then raise exception 'preset_publish_forbidden'; end if;
  select coalesce(max(version_number), 0) + 1 into next_number from public.preset_versions where preset_id = p.id;
  if p.versioning_method = 'semver' then
    next_label := regexp_replace(trim(coalesce(requested_label, '')), '^v', '');
    if next_label !~ '^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(-[0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*)?(\+[0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*)?$' then raise exception 'invalid_semver_label'; end if;
  elsif p.versioning_method = 'date' then
    date_base := to_char(current_date, 'YYYY.MM.DD');
    select count(*) into date_count from public.preset_versions where preset_id = p.id and version_label like date_base || '%';
    next_label := case when date_count = 0 then date_base else date_base || '.' || (date_count + 1)::text end;
  else next_label := 'v' || next_number::text;
  end if;
  insert into public.preset_versions (preset_id, version_number, version_label, versioning_method, name, slug, description, config, visibility, release_notes, created_by)
  values (p.id, next_number, next_label, p.versioning_method, p.draft_name, p.draft_slug, p.draft_description, p.draft_config, p.draft_visibility, nullif(trim(notes), ''), actor_user_id)
  returning * into published;
  update public.presets set name = published.name, slug = published.slug, description = published.description,
    config = published.config, visibility = published.visibility, active_version_id = published.id, updated_at = now()
  where id = p.id;
  return published;
end

declare
  v_meta jsonb;
  v_attempts jsonb;
  v_queue jsonb;
  v_deliveries jsonb;
  v_next_retry_at timestamptz;
  v_telemetry_patch jsonb;
begin
  select coalesce(meta, '{}'::jsonb) into v_meta
  from public.gateway_async_operations
  where workspace_id = p_workspace_id and kind = p_kind and internal_id = p_internal_id
  for update;
  if not found then return; end if;

  v_telemetry_patch := coalesce(p_telemetry_patch, '{}'::jsonb)
    - 'webhookAttempts'
    - 'webhookRetryQueue'
    - 'webhookDeliveries'
    - 'nextWebhookRetryAt'
    - 'lastWebhookDispatchedAt'
    - 'lastWebhookProgress'
    - 'lastWebhookProgressAt';

  v_attempts := coalesce(v_meta->'webhookAttempts', '[]'::jsonb) || jsonb_build_array(p_attempt);
  if jsonb_array_length(v_attempts) > 50 then
    select coalesce(jsonb_agg(value order by ordinality), '[]'::jsonb)
      into v_attempts
    from jsonb_array_elements(v_attempts) with ordinality
    where ordinality > jsonb_array_length(v_attempts) - 50;
  end if;

  v_queue := coalesce(v_meta->'webhookRetryQueue', '{}'::jsonb);
  if p_retry_state is null then
    v_queue := v_queue - p_delivery_key;
  else
    v_queue := jsonb_set(v_queue, array[p_delivery_key], p_retry_state, true);
  end if;

  v_deliveries := coalesce(v_meta->'webhookDeliveries', '{}'::jsonb);
  if p_delivered_at is not null then
    v_deliveries := jsonb_set(v_deliveries, array[p_delivery_key], to_jsonb(p_delivered_at::text), true);
  end if;

  select min(nullif(value->>'nextRetryAt', '')::timestamptz)
    into v_next_retry_at
  from jsonb_each(v_queue);

  v_meta := v_meta || jsonb_build_object(
    'webhookAttempts', v_attempts,
    'webhookRetryQueue', v_queue,
    'webhookDeliveries', v_deliveries,
    'nextWebhookRetryAt', case when v_next_retry_at is null then 'null'::jsonb else to_jsonb(v_next_retry_at::text) end,
    'lastWebhookDispatchedAt', to_jsonb(now()::text)
  ) || v_telemetry_patch;
  if p_progress is not null then
    v_meta := v_meta || jsonb_build_object(
      'lastWebhookProgress', p_progress,
      'lastWebhookProgressAt', to_jsonb(now()::text)
    );
  end if;

  update public.gateway_async_operations
  set meta = v_meta, updated_at = now()
  where workspace_id = p_workspace_id and kind = p_kind and internal_id = p_internal_id;

  update public.gateway_async_webhook_deliveries
  set status = case
        when p_delivered_at is not null then 'delivered'
        when p_next_retry_at is null then 'failed'
        else status
      end,
      claim_token = case when p_next_retry_at is null then null else claim_token end,
      claimed_at = case when p_next_retry_at is null then null else claimed_at end,
      delivered_at = coalesce(p_delivered_at, delivered_at),
      next_attempt_at = p_next_retry_at,
      last_error = p_attempt->>'error_message',
      updated_at = now()
  where workspace_id = p_workspace_id and kind = p_kind
    and internal_id = p_internal_id and delivery_key = p_delivery_key;
end;

declare
  request_row record;
  provider_slug_value text;
begin
  select fact.occurred_at, coalesce(fact.routed_model_slug, fact.requested_model_slug) as model_slug
    into request_row
  from public.v2_request_facts fact
  where fact.request_event_id = new.request_event_id;
  if request_row.model_slug is null or new.provider_model_id is null then return new; end if;

  select route.provider_slug into provider_slug_value
  from public.v2_model_provider_routes route
  where route.provider_model_id = new.provider_model_id;
  if provider_slug_value is null then return new; end if;

  delete from public.v2_public_provider_health_daily
  where usage_date = request_row.occurred_at::date
    and model_slug = request_row.model_slug
    and provider_model_id = new.provider_model_id;

  insert into public.v2_public_provider_health_daily (
    usage_date, model_slug, provider_model_id, provider_slug, request_count,
    successful_request_count, attempt_count, successful_attempts, failed_attempts,
    fallback_attempts, latency_sum_ms, latency_count
  )
  select request_row.occurred_at::date, request_row.model_slug, new.provider_model_id, provider_slug_value,
    count(distinct fact.request_event_id), count(distinct fact.request_event_id) filter (where attempt.success),
    count(*), count(*) filter (where attempt.success), count(*) filter (where not attempt.success),
    count(*) filter (where attempt.attempt_number > 1),
    coalesce(sum(attempt.latency_ms) filter (where attempt.latency_ms is not null), 0), count(attempt.latency_ms)
  from public.v2_request_attempts attempt
  join public.v2_request_facts fact on fact.request_event_id = attempt.request_event_id
  where fact.occurred_at::date = request_row.occurred_at::date
    and coalesce(fact.routed_model_slug, fact.requested_model_slug) = request_row.model_slug
    and attempt.provider_model_id = new.provider_model_id;
  return new;
end;

declare
  v_user_id uuid := auth.uid();
  v_req public.team_join_requests%rowtype;
begin
  if v_user_id is null then
    raise exception using errcode = '42501', message = 'Unauthorized';
  end if;

  select *
    into v_req
  from public.team_join_requests
  where team_join_requests.id = p_request_id
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'Join request not found';
  end if;

  if v_req.status <> 'pending'::public.join_request_status then
    raise exception using errcode = '23514', message = 'Request already decided';
  end if;

  if not public.is_team_admin(v_req.team_id) then
    raise exception using errcode = '42501', message = 'Only owners or admins may reject join requests.';
  end if;

  return query
  update public.team_join_requests r
     set status = 'denied'::public.join_request_status,
         decided_by = v_user_id,
         decided_at = now()
   where r.id = v_req.id
     and r.status = 'pending'::public.join_request_status
  returning r.id, r.team_id;

  if not found then
    raise exception using errcode = '23514', message = 'Request already decided';
  end if;
end;

declare
  workspace_row public.workspaces%rowtype;
  normalized_handle text := lower(trim(requested_handle));
begin
  if normalized_handle !~ '^[a-z0-9][a-z0-9_-]{2,39}$' then
    raise exception 'invalid_publisher_handle';
  end if;

  select * into workspace_row
  from public.workspaces
  where id = target_workspace_id
  for update;
  if not found then raise exception 'workspace_not_found'; end if;

  if workspace_row.owner_user_id <> actor_user_id and not exists (
    select 1 from public.workspace_members member
    where member.workspace_id = target_workspace_id
      and member.user_id = actor_user_id
      and member.role in ('owner', 'admin')
  ) then
    raise exception 'publisher_handle_forbidden';
  end if;

  if normalized_handle = workspace_row.publisher_handle then
    return normalized_handle;
  end if;

  if exists (
    select 1 from public.workspaces workspace
    where lower(workspace.publisher_handle) = normalized_handle
      and workspace.id <> target_workspace_id
  ) or exists (
    select 1 from public.workspace_publisher_handle_aliases alias
    where alias.handle = normalized_handle
      and alias.workspace_id <> target_workspace_id
  ) then
    raise exception 'publisher_handle_reserved' using errcode = '23505';
  end if;

  insert into public.workspace_publisher_handle_aliases (handle, workspace_id)
  values (workspace_row.publisher_handle, target_workspace_id)
  on conflict (handle) do nothing;

  delete from public.workspace_publisher_handle_aliases
  where workspace_id = target_workspace_id and handle = normalized_handle;

  update public.workspaces
  set publisher_handle = normalized_handle
  where id = target_workspace_id;

  return normalized_handle;
end

declare
  current_key public.byok_keys%rowtype;
  adjacent_key public.byok_keys%rowtype;
begin
  if p_direction not in ('up', 'down') then
    raise exception using errcode = '22023', message = 'invalid_direction';
  end if;
  if not public.is_workspace_admin(p_workspace_id) then
    raise exception using errcode = '42501', message = 'forbidden';
  end if;

  select * into current_key
  from public.byok_keys
  where id = p_key_id and workspace_id = p_workspace_id
  for update;
  if not found then return false; end if;

  if p_direction = 'up' then
    select * into adjacent_key
    from public.byok_keys
    where workspace_id = current_key.workspace_id
      and provider_id = current_key.provider_id
      and routing_mode = current_key.routing_mode
      and (sort_order, created_at, id) < (current_key.sort_order, current_key.created_at, current_key.id)
    order by sort_order desc, created_at desc, id desc
    limit 1
    for update;
  else
    select * into adjacent_key
    from public.byok_keys
    where workspace_id = current_key.workspace_id
      and provider_id = current_key.provider_id
      and routing_mode = current_key.routing_mode
      and (sort_order, created_at, id) > (current_key.sort_order, current_key.created_at, current_key.id)
    order by sort_order, created_at, id
    limit 1
    for update;
  end if;
  if not found then return true; end if;

  update public.byok_keys
  set sort_order = case
    when id = current_key.id then adjacent_key.sort_order
    else current_key.sort_order
  end
  where id in (current_key.id, adjacent_key.id);
  return true;
end;

begin
  if exists (
    select 1
    from unnest(coalesce(p_key_ids, '{}'::uuid[])) requested(key_id)
    left join public.keys gateway_key on gateway_key.id = requested.key_id
    left join public.gateway_dynamic_routes route on route.id = p_route_id
    where gateway_key.id is null
      or route.id is null
      or gateway_key.workspace_id <> route.workspace_id
  ) then
    raise exception 'dynamic_route_key_workspace_mismatch';
  end if;

  delete from public.gateway_dynamic_route_keys
  where route_id = p_route_id
    or key_id = any(coalesce(p_key_ids, '{}'::uuid[]));

  insert into public.gateway_dynamic_route_keys (route_id, key_id, attached_by)
  select p_route_id, requested.key_id, p_attached_by
  from unnest(coalesce(p_key_ids, '{}'::uuid[])) requested(key_id);
end;

declare
  v_plan_uuid uuid;
  v_models jsonb := coalesce(p_models, '[]'::jsonb);
  v_features jsonb := coalesce(p_features, '[]'::jsonb);
begin
  if p_plan is null then raise exception 'p_plan is required'; end if;
  if jsonb_typeof(v_models) <> 'array' then raise exception 'p_models must be a JSON array'; end if;
  if jsonb_typeof(v_features) <> 'array' then raise exception 'p_features must be a JSON array'; end if;

  v_plan_uuid := nullif(p_plan->>'plan_uuid', '')::uuid;
  if v_plan_uuid is null then raise exception 'p_plan.plan_uuid is required'; end if;

  insert into public.v2_subscription_plans (
    plan_uuid, plan_id, name, lab_slug, description, frequency,
    price, currency, link, other_info, created_at, updated_at
  ) values (
    v_plan_uuid,
    p_plan->>'plan_id',
    p_plan->>'name',
    p_plan->>'organisation_id',
    p_plan->>'description',
    p_plan->>'frequency',
    nullif(p_plan->>'price', '')::numeric,
    p_plan->>'currency',
    p_plan->>'link',
    coalesce(p_plan->'other_info', '{}'::jsonb),
    coalesce(nullif(p_plan->>'created_at', '')::timestamptz, now()),
    now()
  )
  on conflict (plan_uuid) do update set
    plan_id = excluded.plan_id,
    name = excluded.name,
    lab_slug = excluded.lab_slug,
    description = excluded.description,
    frequency = excluded.frequency,
    price = excluded.price,
    currency = excluded.currency,
    link = excluded.link,
    other_info = excluded.other_info,
    updated_at = now();

  delete from public.v2_subscription_plan_models where plan_uuid = v_plan_uuid;
  insert into public.v2_subscription_plan_models (
    plan_uuid, model_slug, model_info, rate_limit, other_info
  )
  select
    v_plan_uuid,
    model.model_id,
    coalesce(model.model_info, '{}'::jsonb),
    coalesce(model.rate_limit, '{}'::jsonb),
    coalesce(model.other_info, '{}'::jsonb)
  from jsonb_to_recordset(v_models) as model(
    plan_uuid uuid, model_id text, model_info jsonb, rate_limit jsonb, other_info jsonb
  );

  delete from public.v2_subscription_plan_features where plan_uuid = v_plan_uuid;
  insert into public.v2_subscription_plan_features (
    plan_uuid, feature_name, feature_value, feature_description, other_info
  )
  select
    v_plan_uuid,
    feature.feature_name,
    case
      when feature.feature_value is null then null
      when jsonb_typeof(feature.feature_value) = 'string' then feature.feature_value #>> '{}'
      else feature.feature_value::text
    end,
    feature.feature_description,
    coalesce(feature.other_info, '{}'::jsonb)
  from jsonb_to_recordset(v_features) as feature(
    plan_uuid uuid, feature_name text, feature_value jsonb,
    feature_description text, other_info jsonb
  );
end;

begin
  update public.oauth_authorizations
  set revoked_at = coalesce(revoked_at, now())
  where user_id = old.user_id
    and workspace_id = old.workspace_id
    and revoked_at is null;

  update public.oauth_refresh_tokens
  set revoked_at = coalesce(revoked_at, now())
  where user_id = old.user_id
    and workspace_id = old.workspace_id
    and revoked_at is null;

  return old;
end;

DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;

declare
  token_identity public.oauth_refresh_tokens%rowtype;
  current_token public.oauth_refresh_tokens%rowtype;
  token_family uuid;
  granted_scopes text[];
begin
  -- Read identity without a row lock. Taking the token lock here would invert
  -- the member-delete trigger's membership -> authorization -> token order.
  select * into token_identity
  from public.oauth_refresh_tokens
  where token_hash = p_current_token_hash;

  if not found then
    return 'invalid';
  end if;

  perform 1
  from public.workspace_members member
  where member.user_id = token_identity.user_id
    and member.workspace_id = token_identity.workspace_id
  for key share;

  if not found then
    return 'invalid';
  end if;

  select authorization_row.scopes into granted_scopes
  from public.oauth_authorizations authorization_row
  where authorization_row.user_id = token_identity.user_id
    and authorization_row.workspace_id = token_identity.workspace_id
    and authorization_row.client_id = token_identity.client_id
    and authorization_row.revoked_at is null
  for update;

  if not found then
    return 'invalid';
  end if;

  -- Re-read and validate after acquiring locks because another rotation may
  -- have changed this token between the initial identity read and this lock.
  select * into current_token
  from public.oauth_refresh_tokens
  where token_hash = p_current_token_hash
  for update;

  if not found
    or current_token.user_id <> token_identity.user_id
    or current_token.workspace_id <> token_identity.workspace_id
    or current_token.client_id <> token_identity.client_id then
    return 'invalid';
  end if;

  token_family := coalesce(current_token.family_id, current_token.id);

  if current_token.revoked_at is not null then
    update public.oauth_refresh_tokens
    set revoked_at = coalesce(revoked_at, now())
    where family_id = token_family;
    return 'reused';
  end if;

  if current_token.expires_at is not null and current_token.expires_at <= now() then
    update public.oauth_refresh_tokens set revoked_at = now() where id = current_token.id;
    return 'invalid';
  end if;

  update public.oauth_refresh_tokens
  set revoked_at = now(), last_used_at = now()
  where id = current_token.id;

  insert into public.oauth_refresh_tokens (
    token_hash, user_id, workspace_id, client_id, scopes, expires_at,
    rotated_from, family_id
  ) values (
    p_next_token_hash, current_token.user_id, current_token.workspace_id,
    current_token.client_id, granted_scopes, p_next_expires_at,
    current_token.id, token_family
  );

  return 'rotated';
end;

begin
  -- Only bump updated_at if some column changed,
  -- and we haven't already set updated_at in this trigger.
  if row(NEW.*) is distinct from row(OLD.*)
     and NEW.updated_at is not distinct from OLD.updated_at then
    NEW.updated_at := now();
  end if;
  return NEW;
end;

declare
    v_existing public.credit_ledger%rowtype;
    v_before bigint;
    v_after bigint;
    v_kind text;
begin
    if p_workspace_id is null then
        raise exception 'missing_workspace_id';
    end if;

    if coalesce(trim(p_payment_intent_id), '') = '' then
        raise exception 'missing_payment_intent_id';
    end if;

    if p_amount_nanos is null or p_amount_nanos <= 0 then
        raise exception 'invalid_amount_nanos';
    end if;

    v_kind := case lower(coalesce(trim(p_kind), ''))
        when 'top_up_one_off' then 'top_up_one_off'
        when 'auto_top_up' then 'auto_top_up'
        else 'top_up'
    end;

    select *
    into v_existing
    from public.credit_ledger
    where ref_type = 'Stripe_Payment_Intent'
      and ref_id = p_payment_intent_id
    for update;

    if found and v_existing.workspace_id is not null and v_existing.workspace_id <> p_workspace_id then
        raise exception 'payment_intent_workspace_mismatch';
    end if;

    if found and lower(coalesce(v_existing.status, '')) in ('paid', 'succeeded') then
        return query
        select
            false,
            coalesce(v_existing.before_balance_nanos, 0)::bigint,
            coalesce(v_existing.after_balance_nanos, 0)::bigint,
            coalesce(v_existing.status, 'Paid');
        return;
    end if;

    if not found then
        insert into public.credit_ledger (
            workspace_id,
            kind,
            amount_nanos,
            before_balance_nanos,
            after_balance_nanos,
            ref_type,
            ref_id,
            status,
            event_time
        ) values (
            p_workspace_id,
            v_kind,
            0,
            0,
            0,
            'Stripe_Payment_Intent',
            p_payment_intent_id,
            'Applying',
            coalesce(p_event_time, now())
        );
    end if;

    update public.wallets
    set balance_nanos = balance_nanos + p_amount_nanos,
        updated_at = now()
    where workspace_id = p_workspace_id
    returning balance_nanos - p_amount_nanos, balance_nanos
    into v_before, v_after;

    if not found then
        raise exception 'wallet_not_found';
    end if;

    update public.credit_ledger
    set workspace_id = p_workspace_id,
        kind = v_kind,
        amount_nanos = p_amount_nanos,
        before_balance_nanos = v_before,
        after_balance_nanos = v_after,
        status = 'Paid',
        event_time = coalesce(p_event_time, now())
    where ref_type = 'Stripe_Payment_Intent'
      and ref_id = p_payment_intent_id;

    return query
    select true, v_before, v_after, 'Paid';
end;

declare
    v_purchase public.credit_ledger%rowtype;
    v_usage_nanos bigint := 0;
    v_has_active_refund boolean := false;
    v_claim_state text;
begin
    select *
    into v_purchase
    from public.credit_ledger
    where team_id = p_team_id
      and ref_type = 'Stripe_Payment_Intent'
      and ref_id = p_payment_intent_id
      and kind in ('top_up', 'top_up_one_off', 'auto_top_up')
    for update;

    if not found then
        return query select false, 'purchase_not_found', 0::bigint, 0::bigint, null::timestamptz;
        return;
    end if;

    if lower(coalesce(v_purchase.status, '')) not in ('paid', 'succeeded') then
        return query select false, 'purchase_not_paid', 0::bigint, 0::bigint, v_purchase.event_time;
        return;
    end if;

    if v_purchase.event_time < now() - interval '24 hours' then
        return query select false, 'window_expired', 0::bigint, 0::bigint, v_purchase.event_time;
        return;
    end if;

    v_claim_state := coalesce(v_purchase.refund_claim_state, '');
    if v_claim_state not in ('', 'Failed', 'Canceled', 'Rejected') then
        return query select false, 'refund_claim_in_progress', 0::bigint, 0::bigint, v_purchase.event_time;
        return;
    end if;

    select exists (
        select 1
        from public.credit_ledger cl
        where cl.team_id = p_team_id
          and cl.kind = 'refund'
          and cl.source_ref_type = 'Stripe_Payment_Intent'
          and cl.source_ref_id = p_payment_intent_id
          and coalesce(cl.status, '') in ('Pending', 'Applying', 'Processing', 'Succeeded')
    ) into v_has_active_refund;

    if v_has_active_refund then
        update public.credit_ledger
        set refund_claim_state = 'Requested',
            refund_claim_reason = 'Refund already in progress.',
            refund_claimed_at = now(),
            refund_claimed_by_user_id = p_user_id
        where id = v_purchase.id;

        return query select false, 'refund_already_exists', 0::bigint, v_purchase.before_balance_nanos, v_purchase.event_time;
        return;
    end if;

    select coalesce(sum(gr.cost_nanos), 0)::bigint
    into v_usage_nanos
    from private.v2_rpc_gateway_requests_compat gr
    where gr.team_id = p_team_id
      and gr.success is true
      and gr.created_at >= v_purchase.event_time;

    if v_usage_nanos > coalesce(v_purchase.before_balance_nanos, 0) then
        update public.credit_ledger
        set refund_claim_state = 'Rejected',
            refund_claim_reason = 'Credits from this top-up have already been used.',
            refund_claimed_at = now(),
            refund_claimed_by_user_id = p_user_id
        where id = v_purchase.id;

        return query select false, 'lot_used', 0::bigint, v_purchase.before_balance_nanos, v_purchase.event_time;
        return;
    end if;

    update public.credit_ledger
    set refund_claim_state = 'Applying',
        refund_claim_reason = null,
        refund_claimed_at = now(),
        refund_claimed_by_user_id = p_user_id
    where id = v_purchase.id;

    return query select true, null::text, v_purchase.amount_nanos, v_purchase.before_balance_nanos, v_purchase.event_time;
end;

begin
  if new.name is distinct from old.name and old.draft_name is not distinct from old.name then new.draft_name := new.name; end if;
  if new.slug is distinct from old.slug and old.draft_slug is not distinct from old.slug then new.draft_slug := new.slug; end if;
  if new.description is distinct from old.description and old.draft_description is not distinct from old.description then new.draft_description := new.description; end if;
  if new.config is distinct from old.config and old.draft_config is not distinct from old.config then new.draft_config := new.config; end if;
  if new.visibility is distinct from old.visibility and old.draft_visibility is not distinct from old.visibility then new.draft_visibility := new.visibility; end if;
  return new;
end

begin
  new.edge_country := case
    when nullif(new.safe_metadata->>'edge_country', '') ~ '^[A-Za-z]{2}$'
      then upper(new.safe_metadata->>'edge_country')
    else null
  end;
  new.edge_continent := case
